INSERT INTO `compared_images` (`id`, `user_id`, `image`, `target_image`, `subject_image`, `comment`, `created`, `updated`, `active`) VALUES
(5, 12, 'https://ashiyasebikyaku.com/uploads/662dd15aafe0b.png', 1575, 1565, '', '2024-04-28 13:32:26', '2024-04-28 04:32:26', 0),
(6, 12, 'https://ashiyasebikyaku.com/uploads/662dd18b7099c.png', 1574, 1564, '', '2024-04-28 13:33:15', '2024-04-28 04:33:15', 0),
(9, 19, 'https://ashiyasebikyaku.com/uploads/66322c0b9fc47.png', 1743, 1719, '＊お腹スッキリ\r\n＊ふくらはぎの横幅減、外張り減\r\n＊アゴのラインもシュッ', '2024-05-01 20:48:27', '2024-05-01 11:48:27', 1),
(12, 19, 'https://ashiyasebikyaku.com/uploads/66322f3d8ef8a.png', 1746, 1722, '＊左の肩甲骨クッキリしてきた\r\n＊ウェスト細くなった\r\n＊カカトの位置が揃ってきた\r\n＊腰の捩れが取れてくればヒップが上がる。ふくらはぎの外ハリが取れてくる。', '2024-05-01 21:02:05', '2024-05-01 12:02:05', 1),
(13, 19, 'https://ashiyasebikyaku.com/uploads/6632308d29106.png', 1745, 1721, '＊首の位置が重力線にのってきた。首が長くなった\r\n＊胸の位置が上がった\r\n＊ウェストが薄くなった', '2024-05-01 21:07:41', '2024-05-01 12:07:41', 0),
(15, 19, 'https://ashiyasebikyaku.com/uploads/6632329cc523c.png', 1744, 1720, '＊前モモのハリが減少\r\n＊ふくらはぎの横幅が減少、トップ位置が上がった', '2024-05-01 21:16:28', '2024-05-01 12:16:28', 0),
(19, 19, 'https://ashiyasebikyaku.com/uploads/6638801c5103a.png', 1767, 1744, '＊お尻の丸みが出て上がってきた\r\n＊前ももがスッキリ。横幅も減少', '2024-05-06 16:00:44', '2024-05-06 07:00:44', 1),
(20, 19, 'https://ashiyasebikyaku.com/uploads/663880e7b4a53.png', 1766, 1743, '＊大転子の位置が上がってきた\r\n＊脚の隙間ができてきた', '2024-05-06 16:04:07', '2024-05-06 07:04:07', 1),
(22, 19, 'https://ashiyasebikyaku.com/uploads/663882023ed93.png', 1768, 1745, '＊首の位置が骨盤の上にのってきた\r\n＊膝下長くなった', '2024-05-06 16:08:50', '2024-05-06 07:08:50', 1),
(23, 19, 'https://ashiyasebikyaku.com/uploads/663882fe229ee.png', 1769, 1746, '＊肩甲骨の形がクッキリしてきた\r\n＊腰のくびれの左右差が少し改善', '2024-05-06 16:13:02', '2024-05-06 07:13:02', 1),
(24, 3, 'https://ashiyasebikyaku.com/uploads/6638b7de8321b.png', 1755, 1708, '＊大転子の位置が上がった\r\n＊ふくらはぎの外ハリ部が減少、膝が小さくなった', '2024-05-06 19:58:38', '2024-05-06 10:58:38', 1),
(25, 3, 'https://ashiyasebikyaku.com/uploads/6638b94892da0.png', 1756, 1709, '＊腿の前はりとふくらはぎの後ろハリが減少', '2024-05-06 20:04:40', '2024-05-06 11:04:40', 1),
(26, 3, 'https://ashiyasebikyaku.com/uploads/6638baa4e7dc2.png', 1757, 1710, '＊デコルテが上がった\r\n＊足指が床を踏めてきた', '2024-05-06 20:10:28', '2024-05-06 11:10:28', 1),
(30, 3, 'https://ashiyasebikyaku.com/uploads/6638be433ec1e.png', 1758, 1711, '＊腕の長さが揃った\r\n＊ふくらはぎの外ハリが減少、改善', '2024-05-06 20:25:55', '2024-05-06 11:25:55', 1),
(31, 10, 'https://ashiyasebikyaku.com/uploads/663a37062401e.png', 1778, 1731, '＊ウェストにくびれができてきた\r\n＊腿、スッキリ。特に左脚', '2024-05-07 23:13:26', '2024-05-07 14:13:26', 1),
(32, 10, 'https://ashiyasebikyaku.com/uploads/663a380f6cdcd.png', 1779, 1732, '＊肋骨の開きが改善してきた\r\n＊腿の横幅が減少', '2024-05-07 23:17:51', '2024-05-07 14:17:51', 1),
(34, 10, 'https://ashiyasebikyaku.com/uploads/663a39db7e3a3.png', 1780, 1733, '＊胸の前側が開いてきて前肩が改善\r\n＊ヒップに厚みが出てきた', '2024-05-07 23:25:31', '2024-05-07 14:25:31', 1),
(35, 10, 'https://ashiyasebikyaku.com/uploads/663a3ac05c7a3.png', 1781, 1734, '＊左右の肩甲骨が均等になってきた\r\n＊骨盤の捻れが改善してきた', '2024-05-07 23:29:20', '2024-05-07 14:29:20', 1),
(37, 19, 'https://ashiyasebikyaku.com/uploads/6641fe4a82090.png', 1793, 1766, '', '2024-05-13 20:49:30', '2024-05-13 11:49:30', 0),
(39, 3, 'https://ashiyasebikyaku.com/uploads/66436dbf1d405.png', 1805, 1755, '＊足首の隙間が狭くなってきた', '2024-05-14 22:57:19', '2024-05-14 13:57:19', 1),
(41, 3, 'https://ashiyasebikyaku.com/uploads/66436f6839f1b.png', 1806, 1756, '＊胸椎が進展してきたので胸の位置が上がった\r\n＊ヒップの始まり位置が上がってきた', '2024-05-14 23:04:24', '2024-05-14 14:04:24', 1),
(43, 3, 'https://ashiyasebikyaku.com/uploads/66437141bdcd3.png', 1807, 1757, '＊首の位置が肩の上に乗ってきた\r\n＊重心の位置が整ってきた', '2024-05-14 23:12:17', '2024-05-14 14:12:17', 1),
(44, 3, 'https://ashiyasebikyaku.com/uploads/664372814a0a8.png', 1808, 1758, '＊骨盤の捻れがやや改善\r\n＊右足首が立ってきたのでふくらはぎの外ハリが減った', '2024-05-14 23:17:37', '2024-05-14 14:17:37', 1),
(45, 19, 'https://ashiyasebikyaku.com/uploads/6643751a1d5d8.png', 1793, 1766, '＊ウェストのくびれが左右均等に揃ってきた\r\n＊足首が立ってきてふくらはぎの隙間が狭くなってきた', '2024-05-14 23:28:42', '2024-05-14 14:28:42', 1),
(46, 19, 'https://ashiyasebikyaku.com/uploads/664376c39ce82.png', 1794, 1767, '＊首の位置が肩の上に乗ってきた\r\n＊下尻の位置が上がってきた', '2024-05-14 23:35:47', '2024-05-14 14:35:47', 1),
(47, 19, 'https://ashiyasebikyaku.com/uploads/664377ae538d1.png', 1795, 1768, '＊肋骨を前に押さなくなってきた\r\n＊脚の指が踏めてきた', '2024-05-14 23:39:42', '2024-05-14 14:39:42', 1),
(50, 19, 'https://ashiyasebikyaku.com/uploads/66437cafef4d4.png', 1796, 1769, '＊肋骨の捻れが改善して、首位置が中心に。ウェストのくびれとお尻の形が左右均等に近づいた。\r\n＊足首の歪みも取れてきた\r\n', '2024-05-15 00:01:03', '2024-05-14 15:01:03', 1),
(51, 12, 'https://ashiyasebikyaku.com/uploads/664486829e8fa.png', 1577, 1578, 'テスト', '2024-05-15 18:55:14', '2024-05-15 09:55:14', 0),
(53, 10, 'https://ashiyasebikyaku.com/uploads/664491cb3ef18.png', 1816, 1778, '＊へそ下のお肉取れた\r\n＊膝がまた少し小さくなった\r\n＊膝下スッキリ', '2024-05-15 19:43:23', '2024-05-15 10:43:23', 1),
(55, 10, 'https://ashiyasebikyaku.com/uploads/664492aebcea0.png', 1817, 1779, '＊ヒップ位置が上がった\r\n＊ふくらはぎと足首のメリハリついてきた', '2024-05-15 19:47:10', '2024-05-15 10:47:10', 1),
(56, 10, 'https://ashiyasebikyaku.com/uploads/6644935378436.png', 1818, 1780, '＊バスト位置が上がった\r\n＊下腹薄くなった', '2024-05-15 19:49:55', '2024-05-15 10:49:55', 1),
(59, 10, 'https://ashiyasebikyaku.com/uploads/6644949ac47c2.png', 1819, 1781, '＊背面全体がスッキリ！\r\nモモ裏のもたつき感がなくなってきた', '2024-05-15 19:55:22', '2024-05-15 10:55:22', 1),
(60, 15, 'https://ashiyasebikyaku.com/uploads/6644bdccaa643.png', 1449, 1450, 'tesuto', '2024-05-15 22:51:08', '2024-05-15 13:51:08', 0),
(61, 15, 'https://ashiyasebikyaku.com/uploads/6644be005db58.png', 1449, 1450, '', '2024-05-15 22:52:00', '2024-05-15 13:52:00', 0),
(62, 15, 'https://ashiyasebikyaku.com/uploads/6644c4efafc54.png', 1449, 1450, '', '2024-05-15 23:21:35', '2024-05-15 14:21:35', 0),
(63, 19, 'https://ashiyasebikyaku.com/uploads/664b19a533bd4.png', 1841, 1794, '', '2024-05-20 18:36:37', '2024-05-20 09:36:37', 0),
(64, 3, 'https://ashiyasebikyaku.com/uploads/664eeba1a37e7.png', 1829, 1805, '＊大転子の位置が上がってきた！\r\n＊足首が更に真っ直ぐ立ってきた', '2024-05-23 16:09:21', '2024-05-23 07:09:21', 1),
(67, 3, 'https://ashiyasebikyaku.com/uploads/664eee2474a40.png', 1830, 1806, '＊胸椎が伸びてきた。\r\n＊膝ピンが改善したのでくるぶしラインに膝の位置がのってきた。', '2024-05-23 16:20:04', '2024-05-23 07:20:04', 1),
(73, 3, 'https://ashiyasebikyaku.com/uploads/664ef235bcbd0.png', 1831, 1807, '＊ヒップのスタート位置が更に上がってきた。\r\n＊前腿の張りが改善。\r\n＊ふくらはぎのトップ位置が上がってきた。', '2024-05-23 16:37:25', '2024-05-23 07:37:25', 1),
(76, 3, 'https://ashiyasebikyaku.com/uploads/664ef46203118.png', 1832, 1808, '＊二の腕スッキリ。\r\n＊骨盤の捻れが取れてきてお尻が更にコンパクトになってきた。', '2024-05-23 16:46:42', '2024-05-23 07:46:42', 1),
(79, 16, 'https://ashiyasebikyaku.com/uploads/665334b12697d.png', 1852, 1594, '＊みぞおちのあたりがスッキリ\r\n＊太もものムチムチ感が減った\r\n＊ふくらはぎの太い部分の位置が上がったので足首がスッキリ（特に内側）', '2024-05-26 22:10:09', '2024-05-26 13:10:09', 1),
(80, 16, 'https://ashiyasebikyaku.com/uploads/6653367365da5.png', 1853, 1595, '＊骨盤の位置がニュートラルになってきた\r\n＊膝ピンが改善。前もものハリが減った', '2024-05-26 22:17:39', '2024-05-26 13:17:39', 1),
(84, 18, 'https://ashiyasebikyaku.com/uploads/66534197c9597.png', 1662, 1527, '', '2024-05-26 23:05:11', '2024-05-26 14:05:11', 0),
(85, 18, 'https://ashiyasebikyaku.com/uploads/66534629aa2f5.png', 1662, 1527, '', '2024-05-26 23:24:41', '2024-05-26 14:24:41', 0),
(86, 12, 'https://ashiyasebikyaku.com/uploads/6653494503f9d.png', 1604, 1574, '', '2024-05-26 23:37:57', '2024-05-26 14:37:57', 0),
(87, 12, 'https://ashiyasebikyaku.com/uploads/66534ed6cc5b7.png', 1557, 1520, '', '2024-05-27 00:01:42', '2024-05-26 15:01:42', 0),
(88, 18, 'https://ashiyasebikyaku.com/uploads/66535017174a6.png', 1527, 1662, '', '2024-05-27 00:07:03', '2024-05-26 15:07:03', 0),
(89, 16, 'https://ashiyasebikyaku.com/uploads/66535dc81de5e.png', 1854, 1596, '＊胸椎が上に引き上がってきた→胸を張らなくてもバスト位置がUP!\r\n＊脚全体の形にメリハリがついてきた。\r\n＊ふくらはぎのトップ位置が上がってきた。', '2024-05-27 01:05:28', '2024-05-26 16:05:28', 1),
(90, 16, 'https://ashiyasebikyaku.com/uploads/66535ec5931dd.png', 1855, 1597, '＊腰肉スッキリ。\r\n＊腿裏のセルライト消滅！\r\n＊カカトの歪みが改善！', '2024-05-27 01:09:41', '2024-05-26 16:09:41', 1),
(91, 3, 'https://ashiyasebikyaku.com/uploads/665d7e5534bc4.png', 1875, 1829, '＊首が更に長くなって肩が下がった\r\n＊膝が小さくなって脚のカタチが変わってきた', '2024-06-03 17:27:01', '2024-06-03 08:27:01', 1),
(92, 3, 'https://ashiyasebikyaku.com/uploads/665d7f8d8badf.png', 1876, 1830, '＊背中の頑張ってる感がなくなってきて肩の位置が改善\r\n＊更に重力線にのってきた', '2024-06-03 17:32:13', '2024-06-03 08:32:13', 1),
(94, 3, 'https://ashiyasebikyaku.com/uploads/665d80e245587.png', 1877, 1831, '＊首が肩の上にのってきた\r\n＊バスト位置UP!\r\n＊お尻ができてきた', '2024-06-03 17:37:54', '2024-06-03 08:37:54', 1),
(95, 3, 'https://ashiyasebikyaku.com/uploads/665d825dcd01b.png', 1878, 1832, '＊骨盤の捻れが取れてきた…その分上半身に捻れがでましたが徐々に改善するでしょう\r\n＊脚の形にメリハリがついてきた', '2024-06-03 17:44:13', '2024-06-03 08:44:13', 1),
(96, 19, 'https://ashiyasebikyaku.com/uploads/665d83509f64d.png', 1885, 1863, '＊\r\nウェストの捻れが取れたのが定着してきてくびれができてきた\r\n＊ふくらはぎの外張りが改善\r\n', '2024-06-03 17:48:16', '2024-06-03 08:48:16', 1),
(97, 19, 'https://ashiyasebikyaku.com/uploads/665d83da780c5.png', 1886, 1864, '＊胸椎、上がってきて胸が開いてきた\r\n＊ヒップアップしてきた', '2024-06-03 17:50:34', '2024-06-03 08:50:34', 1),
(98, 19, 'https://ashiyasebikyaku.com/uploads/665d849552d96.png', 1887, 1865, '＊お腹が薄くなった\r\n＊ふくらはぎがスッキリして膝下が長くなった', '2024-06-03 17:53:41', '2024-06-03 08:53:41', 1),
(99, 19, 'https://ashiyasebikyaku.com/uploads/665d8590e476e.png', 1888, 1866, '＊左の肩甲骨がクッキリしてきた\r\n＊大転子の位置が上がってきた\r\n＊膝が正面を向いてきた\r\n＊ふくらはぎの外はりが減って足首がくっついてきた', '2024-06-03 17:57:52', '2024-06-03 08:57:52', 1),
(101, 12, 'https://ashiyasebikyaku.com/uploads/665ede896346a.png', 1604, 1605, '', '2024-06-04 18:29:45', '2024-06-04 09:29:45', 0),
(102, 12, 'https://ashiyasebikyaku.com/uploads/665edeb1c89cc.png', 1604, 1574, '', '2024-06-04 18:30:25', '2024-06-04 09:30:25', 0),
(103, 13, 'https://ashiyasebikyaku.com/uploads/665edef5750b5.png', 1230, 1231, '', '2024-06-04 18:31:33', '2024-06-04 09:31:33', 0),
(104, 13, 'https://ashiyasebikyaku.com/uploads/665edf3adae1f.png', 1230, 1231, '', '2024-06-04 18:32:42', '2024-06-04 09:32:42', 0),
(105, 12, 'https://ashiyasebikyaku.com/uploads/665ee01763416.png', 1604, 1574, '', '2024-06-04 18:36:23', '2024-06-04 09:36:23', 0),
(106, 12, 'https://ashiyasebikyaku.com/uploads/665ee0b15f67d.png', 1604, 1574, '', '2024-06-04 18:38:57', '2024-06-04 09:38:57', 0),
(107, 3, 'https://ashiyasebikyaku.com/uploads/66601617df75a.png', 1897, 1875, '＊上半身が骨盤の上にのってきた\r\n＊大転子の位置が上がった\r\n＊膝のお皿が小さくなった', '2024-06-05 16:39:03', '2024-06-05 07:39:03', 1),
(108, 3, 'https://ashiyasebikyaku.com/uploads/6660171ab3b64.png', 1898, 1876, '＊胸の開きがムリなく自然な感じになってきた\r\n＊重心が中心にのってきた\r\n↑↑\r\nこの位置が定着してくると腿前のハリが取れてきますねー。', '2024-06-05 16:43:22', '2024-06-05 07:43:22', 1),
(109, 3, 'https://ashiyasebikyaku.com/uploads/666017e4c6c50.png', 1899, 1877, '＊バストアップしてる！\r\n＊お尻の位置が上がって仙骨の上にお肉が移動してきた', '2024-06-05 16:46:44', '2024-06-05 07:46:44', 1),
(110, 3, 'https://ashiyasebikyaku.com/uploads/66601b31dbe12.png', 1900, 1878, '＊今回のアフター写真の方のつま先の向きがズレているのでそれに従って骨盤の捻れ方なども変わって見えるのですが、ある意味自然な身体の流れになっているように思います。\r\n＊矢印と⭕️は見ているポイントです。', '2024-06-05 17:00:49', '2024-06-05 08:00:49', 1),
(111, 10, 'https://ashiyasebikyaku.com/uploads/66601eccb429a.png', 1908, 1816, '＊左の鎖骨が見えてきた\r\n＊足首の捻れが取れてきた', '2024-06-05 17:16:12', '2024-06-05 08:16:12', 1),
(113, 10, 'https://ashiyasebikyaku.com/uploads/66601fd264b1e.png', 1909, 1817, '＊肋骨が閉じてきて、仙骨の傾きが改善してきた', '2024-06-05 17:20:34', '2024-06-05 08:20:34', 1),
(114, 10, 'https://ashiyasebikyaku.com/uploads/666020da3c04f.png', 1910, 1818, '＊前肩改善してきた\r\n＊肋骨が閉じた分背中スッキリ\r\n＊膝周辺のお肉取れてきた\r\n＊ふくらはぎのトップが上がった', '2024-06-05 17:24:58', '2024-06-05 08:24:58', 1),
(115, 10, 'https://ashiyasebikyaku.com/uploads/666023bbb38d2.png', 1911, 1819, '＊お尻がコンパクトになってきた\r\n＊腿裏のお肉のもたつきが取れてきた\r\n＊足首が細くなってきた\r\n今回、足首と仙骨が改善してきたと思うのですが、その分少し股関節を捻って調整しているように感じます。', '2024-06-05 17:37:15', '2024-06-05 08:37:15', 1),
(116, 10, 'https://ashiyasebikyaku.com/uploads/6667d5126a5ff.png', 1928, 1908, '＊ウェスト周りスッキリ\r\n＊脚全体のメリハリがついてきた', '2024-06-11 13:39:46', '2024-06-11 04:39:46', 1),
