(427, 6, '2023-11-27', '3', '2', 'サプリ〇 食物繊維〇', 1, '2023-12-01 07:52:57', '2023-12-01 22:54:15'),
(428, 2, '2023-11-30', '2', '2', '基本のワークとマッサージ、ストレッチをしました。保木スペのウォーキングも意識してやってます。', 1, '2023-12-02 21:04:19', '2023-12-03 10:39:46'),
(429, 2, '2023-12-01', '2', '2', '基本のワーク、保木スペのウォーキング、ストレッチ、ヒンジもやってみました。\r\n今週キッチンにたつとき、歯磨きするとき意識しながら後傾をなおすようにしていました。無意識にキッチンによりかからずになってきたかも？？？くらいにはなれたよえな気がします', 1, '2023-12-02 21:12:06', '2023-12-03 10:39:44'),
(430, 2, '2023-12-02', '2', '2', '今日は数年に一回あるかないかの休日出勤でした。仕事内容も大勢の人前でお話をするものだったので、帰宅後ぐったりというわけでご褒美！と称してたくさん食べました(T_T)', 1, '2023-12-03 19:30:47', '2023-12-04 19:40:00'),
(431, 2, '2023-12-03', '2', '2', '１日やすみでしたが、家事に時間を使って基本のワークのみでした。何となくワークをすることを後回しにしがちになってます。中だるみ？「やるぞ！」っていう気持ちの切替がイマイチ。食欲も増加して余計に食べてます。さすがに家族に身体がぷよってきたと言われてしまいました。', 1, '2023-12-04 05:58:11', '2023-12-04 19:40:10'),
(432, 2, '2023-12-04', '2', '2', '基本のワーク、11-4、保木スペできました。ワークを動画なしでやると自己流になってしまい、動画を見直しながらやると時間がかかる。動画をみずに出来るだけ丁寧にやれる方法の模索中です。自分の身体の感覚にフォーカスするようにしたらいいのでしょうか？', 1, '2023-12-05 09:51:15', '2023-12-06 15:26:13'),
(433, 2, '2023-12-05', '2', '2', 'みかん食べました。寒いのとくもりで薄暗いのとで、今日は身体が縮こまって身体をぬるゆるのばしたい気分だったので、ストレッチをメインにやってました', 1, '2023-12-06 08:41:43', '2023-12-06 15:26:29'),
(434, 6, '2023-12-05', '3', '3', 'サプリ◯ 食物繊維◯', 1, '2023-12-06 15:29:27', '2023-12-06 15:32:34'),
(435, 6, '2023-12-04', '2', '2', 'サプリ◯ 食物繊維‪✕‬', 1, '2023-12-06 15:31:05', '2023-12-06 15:32:36'),
(436, 2, '2023-12-06', '2', '2', '職場でインフルエンザが大流行していて、感染していない人の方が少ない状況です。わたしが元気なのは、身体のバランスを整える事で免疫力もあがってるから？と期待してます。今日もみかんを食べ、基本のワークを内観する事に注視しながらやってみました。', 1, '2023-12-07 12:54:24', '2023-12-07 20:45:29'),
(437, 2, '2023-12-07', '2', '2', 'メッセージいただいて、以前のグループレッスンの股関節の回の動画を見ながらやってみました。時々入る「保木さん」のアドバイスを聞いて、いつも同じところを指摘されていて、やっと確かにその通り！と納得しました。その時の感覚より今の方がうち太ももや色々な関節の感覚がわかりやすくなっているので、少しは改善されてるのかな？と思います。', 1, '2023-12-08 20:13:31', '2023-12-09 11:29:18'),
(438, 2, '2023-12-08', '2', '2', '基本のワークと保木スペを中心にやってみました', 1, '2023-12-09 23:37:19', '2023-12-11 09:28:10'),
(439, 6, '2023-12-09', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬‪‪', 1, '2023-12-10 21:16:42', '2023-12-11 09:27:19'),
(440, 6, '2023-12-08', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ〇', 1, '2023-12-10 21:18:35', '2023-12-11 09:27:19'),
(441, 6, '2023-12-07', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ〇', 1, '2023-12-10 21:18:53', '2023-12-11 09:27:17'),
(442, 6, '2023-12-06', '2', '3', 'サプリ〇 食物繊維〇\r\n', 1, '2023-12-10 21:20:18', '2023-12-11 09:27:16'),
(443, 2, '2023-12-09', '2', '2', '今日は、家族の誕生日のお祝いで、ご馳走の日でした。お腹がきつくなってしまいましたが、基本のワークと保木スペ、バックキックをしました。', 1, '2023-12-10 22:11:36', '2023-12-11 09:28:00'),
(444, 2, '2023-12-10', '1', '2', 'じっくり動画を流しながらワークしてみました。自分と向き合える時間があるのはいいです。', 1, '2023-12-11 22:51:04', '2023-12-17 10:20:47'),
(445, 2, '2023-12-11', '2', '2', 'すみません(T_T)毎日の記録を送っているつもりで、送信していなかったようです。\r\n月曜、基本のワークと保木スペやってます', 1, '2023-12-14 20:34:26', '2023-12-17 10:20:46');
INSERT INTO `daily_reports` (`id`, `user_id`, `report_date`, `status`, `intestine_status`, `comment`, `is_checked`, `created`, `modified`) VALUES
(446, 2, '2023-12-12', '2', '2', '火曜も基本のワークと保木スペやってます。ボールにのったとき、骨盤が自然にニュートラル位置になってると思うのですが、立ち姿勢になるとまだまだ後傾になってしまいます。「あっ」と気付いて姿勢を治すようにはしてるのですが。まだまだ？', 1, '2023-12-14 20:36:51', '2023-12-17 10:20:35'),
(447, 2, '2023-12-13', '2', '2', '久しぶりのグループレッスン！とコンサル！楽しかった！！！です。コンサルでふくらはぎ変わった！と言われましたが、翌朝の足がとても軽くて、すごい！', 1, '2023-12-14 20:38:57', '2023-12-17 10:20:29'),
(448, 2, '2023-12-14', '2', '2', '昨日の歩き方の感覚を覚えたくて、リビングで往復して練習していたら、なぜか猫にちょっかいだされてました。集中できない（笑）普段股関節を使えていなかったためなのか、股関節が筋肉痛？です。終わったあとはボールワークでケア調整しました。', 1, '2023-12-15 08:29:13', '2023-12-17 10:20:11'),
(449, 6, '2023-12-14', '3', '2', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-15 12:16:54', '2023-12-17 10:19:44'),
(450, 6, '2023-12-13', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-15 12:17:23', '2023-12-17 10:19:41'),
(451, 6, '2023-12-12', '2', '3', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-15 12:18:45', '2023-12-17 10:19:40'),
(452, 6, '2023-12-11', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ〇', 1, '2023-12-15 12:19:55', '2023-12-17 10:19:39'),
(453, 2, '2023-12-15', '2', '1', '今日も基本のワークとウォーキングをやりました。猫にもちょっかい出されながら頑張りました', 1, '2023-12-16 17:34:10', '2023-12-17 10:20:03'),
(454, 2, '2023-12-16', '2', '2', '基本のワーク、ウォーキングやりました。階段のかかとをつけてのぼるがとても難しい！日頃のクセがよくわかります。今日は久しぶりにバレトンレッスンでした。骨盤の位置、股関節の位置、足先、ひざのむきなどしっかり意識しながらやりました。', 1, '2023-12-17 21:50:23', '2023-12-19 14:03:43'),
(455, 7, '2023-12-18', '2', '1', 'ワーク途中までやりました。\r\n基礎はしっかり。\r\n明日は続きからがんばってみます！', 1, '2023-12-19 02:39:58', '2023-12-19 14:10:06'),
(456, 2, '2023-12-17', '2', '2', 'またしても送ったつもりで、過ごしていました。バレトン翌朝でいつもよりうち太ももが筋肉痛なので、股関節周りのワークを中心にやってみました。ウォーキングもしっかりやってみました', 1, '2023-12-19 19:57:59', '2023-12-21 22:59:19'),
(457, 2, '2023-12-18', '2', '2', '今日はリビングウォーキングを20分くらいやってました。大分掴んだ気はするのですが、普通に歩いていると、内腿意識がとんでいる気がします。', 1, '2023-12-19 20:00:01', '2023-12-21 22:59:00'),
(458, 10, '2023-12-20', '1', '1', '', 1, '2023-12-20 18:41:02', '2023-12-21 23:08:55'),
(459, 6, '2023-12-20', '2', '3', 'サプリ〇食物繊維〇 \r\n筋トレ〇', 1, '2023-12-20 21:48:10', '2023-12-21 23:04:10'),
(460, 2, '2023-12-19', '1', '2', '基本のワークを久しぶりに動画を見ながらやってみました。たまに丁寧にやると身体の感覚をつかみやすいです。リビングウォーキングを今日は15分くらいやってました', 1, '2023-12-20 22:46:21', '2023-12-21 22:58:52'),
(461, 2, '2023-12-20', '2', '2', '今日は、生理が近いためかとても眠くて身体が重だるいです。一番練習のお陰で大分歩きはじめの一歩が踏みだしやすくなりました。', 1, '2023-12-20 22:48:30', '2023-12-21 22:58:42'),
(462, 6, '2023-12-19', '2', '2', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬‪‪', 1, '2023-12-21 20:28:14', '2023-12-21 23:04:08'),
(463, 6, '2023-12-18', '3', '3', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-21 20:28:38', '2023-12-21 23:04:05'),
(464, 6, '2023-12-17', '3', '2', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-21 20:28:56', '2023-12-21 23:04:04'),
(465, 6, '2023-12-16', '3', '3', 'サプリ〇 食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-21 20:29:45', '2023-12-21 23:04:02'),
(466, 6, '2023-12-15', '3', '2', 'サプリ〇食物繊維〇\r\n筋トレ‪✕‬', 1, '2023-12-21 20:30:13', '2023-12-21 23:04:00'),
(467, 2, '2023-12-21', '2', '2', '今朝は裏太ももが筋肉痛でした。昨日のワークでだと思うのですが、自分の筋肉の無さにガッカリです。リビングでウォーキングの練習をしていますが、ふくらはぎが疲れてしまいます。ふくらはぎが力まないようにすると膝が内側に入ってしまいます。', 1, '2023-12-21 21:48:47', '2023-12-21 22:58:24'),
(468, 8, '2023-12-21', '1', '2', '', 1, '2023-12-21 22:04:03', '2023-12-21 23:09:15'),
(469, 11, '2023-12-22', '3', '3', '', 1, '2023-12-23 00:26:58', '2023-12-23 10:16:41'),
(470, 10, '2023-12-21', '1', '1', '', 1, '2023-12-23 11:10:54', '2023-12-24 08:59:44'),
(471, 10, '2023-12-22', '1', '2', '', 1, '2023-12-23 11:11:06', '2023-12-24 08:59:46'),
(472, 2, '2023-12-22', '2', '2', '今日も基本のワークと、保木スペ、ウォーキングできました。内腿の意識で歩くようにしていますが、しっくりこなくて、自分で動画をとって確認すると、歩く時膝が外側に開いていました。内腿から出すの意識を勘違いしてきたようです。', 1, '2023-12-23 22:21:13', '2023-12-24 09:00:52'),
(473, 2, '2023-12-23', '2', '2', '今日は、誕生日でした（笑）歯磨きする時にここ数日立つ時の内腿がピタッとくっついている気がします。太腿がまた太った!?と明日の計測が怖いです。', 1, '2023-12-23 22:23:30', '2023-12-24 09:01:26'),
(474, 11, '2023-12-23', '3', '3', '', 1, '2023-12-24 00:09:50', '2023-12-24 08:59:27'),
(475, 8, '2023-12-23', '2', '2', '', 1, '2023-12-24 00:20:32', '2023-12-24 09:00:04'),
(476, 10, '2023-12-23', '2', '2', '', 1, '2023-12-24 20:56:36', '2023-12-25 14:28:40'),
(477, 10, '2023-12-24', '1', '1', '', 1, '2023-12-24 20:56:54', '2023-12-25 14:28:41'),
(478, 2, '2023-12-24', '2', '2', '基本のワークと保木スペ、ウォーキングできました！が、連日のご馳走三昧で体重増加してます。でも、例年より足の太さはそこまで変化していないので、浮腫みも少ないと思います。いよいよ明日で仕事納めなので、年末年始にじっくり身体と向き合っていきます！', 1, '2023-12-25 08:30:54', '2023-12-25 14:29:43'),
(479, 2, '2023-12-25', '2', '2', '今日は基本のワーク、保木スペやりました。最近、筋トレがやりたくて、軽く楽しく出来るものをとSwitchのリングフィットアドベンチャーをやってみました。ボールワークで感覚を意識しているので、トレーニングするときもここに力が入っていると、腰に負担がかかるとか、理解できているので、以前よりちゃんとトレーニング出来てると感じました。', 1, '2023-12-26 07:03:59', '2023-12-28 21:51:40'),
(480, 2, '2023-12-26', '2', '2', '年末年始の休暇に入りましたが、銀行やら歯科やら子ども関係のアレコレで１日が終わりました。何とか基本のワーク！と動画を見ながらやりました。', 1, '2023-12-27 07:32:02', '2023-12-28 21:52:04'),
(481, 11, '2023-12-26', '1', '1', '', 1, '2023-12-27 09:07:05', '2023-12-28 21:46:48'),
(482, 11, '2023-12-27', '1', '1', '昨日の目標設定のときにしたワークと④をやりました。', 1, '2023-12-27 23:48:55', '2023-12-28 21:46:49'),
(483, 2, '2023-12-27', '1', '2', '今日は、エステの美容整体の日でした。通ってちょうど1年だったので振り返りしましたが、去年よりふくらはぎや太腿のはりかなくなりましたね〜と話してました。せっかくなので今日はワークをフルでやる！と課題のワークやりました。翌朝お尻の位置が高くなってＷ効果を感じました。', 1, '2023-12-28 09:29:31', '2023-12-28 21:52:18'),
(484, 10, '2023-12-25', '1', '2', '', 1, '2023-12-28 13:23:35', '2023-12-28 21:49:28'),
(485, 10, '2023-12-26', '3', '1', '', 1, '2023-12-28 13:23:59', '2023-12-28 21:49:29'),
(486, 10, '2023-12-27', '3', '2', '', 1, '2023-12-28 13:24:12', '2023-12-28 21:49:29'),
(487, 9, '2023-12-28', '1', '', '', 1, '2023-12-29 00:57:12', '2023-12-29 10:05:06'),
(488, 2, '2023-12-28', '2', '2', '基本のワークの他に、20分くらい歩き方を意識して散歩しました。夜のレッスンは、背中肩こりはいつもあるので、本当に永久保存版です！最後の仙骨ワークからの利点の解説も「（やっぱり）そうだったのか！」と納得だったので、基本のワークの大切さを再認識しました。', 1, '2023-12-29 12:11:39', '2023-12-30 13:05:41'),
(489, 9, '2023-12-29', '2', '', '', 1, '2023-12-30 00:55:09', '2023-12-30 13:05:14'),
(490, 11, '2023-12-28', '1', '1', '', 1, '2023-12-30 09:01:30', '2023-12-30 13:04:37'),
(491, 11, '2023-12-29', '3', '2', '', 1, '2023-12-30 09:01:46', '2023-12-30 13:04:39'),
(492, 2, '2023-12-29', '2', '2', '今日は、ほぼ1日外出していたので、歩き方、立ち姿勢に注意しながら行動してました。帰宅後、基本のワークをしていたら若干うち太ももと腹筋が筋肉痛だったので、ちゃんと歩けていたのかな？と思います。', 1, '2023-12-30 11:01:27', '2023-12-30 13:06:18'),
(493, 2, '2023-12-30', '2', '2', '片付けと掃除の１日でした。コンサルの20分前まで、掃除してました（笑）ウォーキングを改善してからずっとうち太ももが筋肉痛です。歩く時、階段登る時、立って作業する時、「はっ！」と思い出してはチェックしてます。「ここに力入ってる」「左右差あるな」とか気づいてはどうすればバランスよくなる？が自分で考えられるようになってきました。なのでワークする時もただやるだけから、今の身体がどう動くかを意識する時間に変化してきました。', 1, '2023-12-31 11:07:39', '2024-01-02 14:50:40'),
(494, 10, '2023-12-28', '3', '1', '', 1, '2023-12-31 18:18:42', '2024-01-02 14:51:56'),
(495, 10, '2023-12-29', '1', '2', '', 1, '2023-12-31 18:18:56', '2024-01-02 14:51:55'),
