(878, 26, '2024-07-10', '2', '2', '今日初めて動画①②をやりました。', 1, '2024-07-10 22:17:40', '2024-07-11 09:06:43'),
(879, 26, '2024-07-11', '2', '3', 'お酒を飲んだら便がゆるくなりました。\r\n帰宅が遅かったため、距骨ワークと足上げぷるぷるだけやりました。', 1, '2024-07-12 07:16:01', '2024-07-12 12:39:08'),
(880, 26, '2024-07-13', '1', '2', 'ワーク1,2,4をやった。歯磨きしながら、足指の上げ下げ運動をした。', 1, '2024-07-14 07:35:26', '2024-07-14 10:08:28'),
(881, 26, '2024-07-14', '1', '2', '動画ワーク①②④をやりました。\r\nお通じはありますが、緩い状態が続いてます。', 1, '2024-07-15 00:32:34', '2024-07-15 08:32:57'),
(882, 26, '2024-07-15', '1', '2', '動画ワーク①②③をやりました。\r\n肋骨にボールをあてて横向きに寝るポーズで右肩を下にしたとき、肩から首にかけてぐっと縮こまって詰まる感じがして、少し痛かったです。ボールの位置が良くないんでしょうか？', 1, '2024-07-15 23:59:59', '2024-07-16 20:56:19'),
(883, 26, '2024-07-16', '1', '1', '動画ワーク①②をやりました。\r\n今日は良い状態の便が出ました。', 1, '2024-07-16 21:50:07', '2024-07-16 21:57:02'),
(884, 26, '2024-07-17', '1', '2', '動画ワーク①②③をやりました。', 1, '2024-07-17 21:26:27', '2024-07-17 21:42:39'),
(885, 26, '2024-07-18', '2', '2', '距骨ワークと足指上げ下げだけやりました。\r\n', 1, '2024-07-19 08:52:59', '2024-07-21 14:14:16'),
(886, 26, '2024-07-19', '1', '2', '動画ワーク①②③をやりました。\r\n③はボールの空気を抜いたら首肩の痛みが軽減しましたが、それでもまだ少し痛いです。', 1, '2024-07-19 21:42:50', '2024-07-21 14:14:20'),
(887, 26, '2024-07-20', '2', '2', '今日はワーク②だけやりました', 1, '2024-07-20 23:42:29', '2024-07-21 14:14:22'),
(888, 28, '2024-07-21', '2', '2', '1の動画のワークとグループレッスンに参加しました。歩く時も仙骨というかお尻を上げて歩くことでしたが、座るときもそのような感じで良いのでしょうか？', 1, '2024-07-21 22:06:02', '2024-07-22 08:51:18'),
(889, 28, '2024-07-22', '2', '2', '今日も動画の1と昨日の重心確認のワークをやりました。\r\n明日は時間が取れそうなので1から3と重心確認のワークをやる予定です。\r\n歩く時は仙骨を意識して歩きました。仙骨をあげて歩くとなると少々反り腰気味な気がするのですが良いのでしょうか？', 0, '2024-07-22 22:33:03', '2024-07-22 22:33:03'),
(890, 26, '2024-07-22', '1', '2', '動画ワーク①とグループレッスンをやりました。\r\n足を振り子のように前後に振ったとき、右足だけ股関節からゴリゴリと音がしました。\r\n股関節が硬いということなんでしょうか？', 1, '2024-07-23 22:15:57', '2024-07-23 22:56:18'),
(891, 28, '2024-07-23', '1', '2', '今日は1から3のワークを動画を見ながらやりました。グループワークで歩き方を見ていただき少し掴めてきた気がします。ただ立っているだけの時前もまた膝上を使っているような感覚があるのでこれはどうしたら良いのでしょうか‥', 1, '2024-07-23 23:59:59', '2024-07-24 11:42:42'),
(892, 28, '2024-07-24', '1', '2', '昨日は早速意識して階段を登ったり降りたりしました！いつもと使ってるところが違うのかわかりました！まだまだ意識することが必要ですが続けていこうと思います。\r\n', 1, '2024-07-25 13:57:23', '2024-07-25 15:56:12'),
(893, 28, '2024-07-25', '1', '2', '朝に足首のワークをやり\r\n寝る前に肋骨と仙骨のワークをやりました。\r\n日常生活では仙骨ウォークを意識しながら過ごしました。\r\n', 1, '2024-07-26 11:11:54', '2024-07-26 22:54:58'),
(894, 28, '2024-07-27', '2', '2', '仙骨ロック外しのワークと足首のワーク、\r\n昨日は外で歩くことが多かったので仙骨を意識しながら歩きました。\r\n久々に電動じゃ無い自転車に乗り重心や仙骨意識はしていたのですが坂道が多く前ももがややきん筋肉痛な気がします💦', 1, '2024-07-28 10:00:55', '2024-07-28 12:20:31'),
(895, 26, '2024-07-28', '2', '2', '今週は外泊続きだったので、距骨ワークとアキレス腱ほぐしだけやっていました。\r\n今日は久しぶりに動画ワーク①をやって、レッスンにも出ました。隙間時間にできることをやっていこうと思います。', 1, '2024-07-28 21:34:38', '2024-07-28 22:27:55'),
(896, 26, '2024-07-29', '2', '2', 'グループレッスンのあと距骨ワークをやりました。階段を上るとき、真下に足を下ろす感覚で上ったら、お尻を使ってる感じがしました。', 1, '2024-07-29 22:11:09', '2024-07-30 00:34:34'),
(897, 28, '2024-07-29', '1', '2', '隙間時間に足首動かしたり呼吸のやつをやりました。グループワークでも緩め方とかも教わったので実践していきます。', 1, '2024-07-30 10:10:00', '2024-07-30 10:31:38'),
(898, 26, '2024-07-30', '1', '2', '動画ワーク①③をやりました。\r\nお手洗いで瞬殺ワークしたり、電車の中で呼吸を意識したりもしました。\r\n仙骨ウォークは、どんどん前に進もうという意識をなくしたら、太ももへの負担が減った気がします。', 1, '2024-07-30 21:02:02', '2024-07-31 14:57:19'),
(899, 26, '2024-07-31', '2', '2', '帰宅が遅かったのでワーク①だけやりました。\r\nすきま時間で瞬殺ワークやったり、呼吸を意識したりしました。これならすきま時間で続けられそうです。', 1, '2024-08-01 13:21:43', '2024-08-01 15:19:09'),
(900, 28, '2024-07-31', '1', '2', '仙骨のロック外しをやる際、教えていただいたように少し下にすると痛くなかったです。', 1, '2024-08-01 14:15:35', '2024-08-01 15:18:12'),
(901, 26, '2024-08-01', '2', '2', 'ワーク①、距骨とアキレス腱のワーク、ボールを腋下に入れるワークをしました。\r\n今日は在宅勤務だったので、ずっと足の下にボールを置いて縦に揺らしてました。\r\n呼吸はまだうまくできませんが、通勤の電車内で毎日やってみようと思います。', 1, '2024-08-02 00:07:04', '2024-08-02 00:44:33'),
(902, 28, '2024-08-01', '2', '2', '1と、2のワークをやりました。\r\nついつい忘れがちですが思い出したら隙間時間にも足首をほぐし、呼吸ワークやっています。仙骨の上の方の痛みが引き続きあるのですが腰がさりすぎなのでしょうか？…\r\nあと座っていると左の股関節に違和感が💦', 1, '2024-08-02 14:22:51', '2024-08-06 11:39:34'),
(903, 26, '2024-08-02', '1', '2', '動画ワーク①②③をやりました。\r\nすきま時間には呼吸ワークや瞬殺ワークもやりました。', 1, '2024-08-03 00:05:39', '2024-08-03 18:39:23'),
(904, 26, '2024-08-03', '1', '2', '仙骨ワークで、片足を伸ばすポーズのとき、前は前ももが張っている感じがしていたが、今日は張りを感じなかった', 1, '2024-08-03 23:23:01', '2024-08-04 22:44:04'),
(905, 26, '2024-08-04', '1', '2', 'ワーク①②③をやりました。呼吸はまだ練習が必要です。', 1, '2024-08-05 00:24:13', '2024-08-05 14:11:27'),
(906, 26, '2024-08-05', '1', '2', '動画ワーク①②③をやりました。\r\n膝下O脚が少し改善した気がしました！', 1, '2024-08-05 23:14:18', '2024-08-05 23:57:15'),
(907, 28, '2024-08-05', '2', '1', '仙骨ウォーク意識していたら足の裏の母指球から小指球にかけてささくれ的な感じになってきましたが力が入りすぎてるのでしょうか？…', 1, '2024-08-06 09:24:41', '2024-08-07 14:51:52'),
(908, 26, '2024-08-06', '1', '2', '動画ワーク①②③をやりました。\r\n今日はいつもより下腹ぽっこりが気にならなかったです。呼吸ワークをやったおかげかな？と思いました', 1, '2024-08-07 00:01:31', '2024-08-07 09:34:13'),
(909, 28, '2024-08-06', '2', '2', '仙骨ロック外しと呼吸のワークはできました！隙間時間活用していきます！', 1, '2024-08-07 12:24:45', '2024-08-07 14:54:15'),
(910, 26, '2024-08-07', '1', '', '動画ワーク①③をやって、グループレッスンに参加しました。昨日、一昨日と少し変化がわかって、楽しくなってきました！', 1, '2024-08-07 23:07:49', '2024-08-07 23:31:37'),
(911, 28, '2024-08-08', '1', '2', 'グループワークで踵の外を踏む感じが少しわかりました。\r\n意識しつつも力みすぎずやっていこうと思います。', 1, '2024-08-08 00:46:06', '2024-08-08 16:55:20'),
(912, 26, '2024-08-08', '1', '2', '動画ワーク①②③をやりました。\r\n先日のグループレッスンでやった立ち方について、太ももを外巻きにするのを日常生活の中で、どう実践したらいいか分かりません。お腹が前に出ないように意識したら良いでしょうか？', 1, '2024-08-09 08:37:31', '2024-08-09 10:37:09'),
(913, 26, '2024-08-09', '2', '2', '今日のグループレッスンは難しかったです。\r\n足首で蹴り上げることを意識して歩いてみます。', 1, '2024-08-09 22:57:26', '2024-08-09 23:00:39'),
(914, 26, '2024-08-10', '1', '2', '動画ワーク①②③をやりました。\r\nテレビ見ながら瞬殺ワークやりました。', 1, '2024-08-10 23:50:54', '2024-08-12 13:42:52'),
(915, 28, '2024-08-11', '2', '2', '昨日は足首を使うことを意識していつもより距離を歩いていたのですが帰宅するとふくらはぎがめっちゃ浮腫んで痛い感じでした…\r\n今日は週間報告の写真を撮りましたが相変わらず背中に丸みがないなと思いました💦', 1, '2024-08-11 23:49:53', '2024-08-12 13:42:23'),
(916, 26, '2024-08-12', '2', '2', '先週は肩の高さが揃ったと思ったのに、この週末はまた左肩が上がってしまいました。', 1, '2024-08-12 23:43:44', '2024-08-12 23:57:11'),
(917, 26, '2024-08-13', '1', '2', '動画ワーク①②③をやりました。\r\nすきま時間に瞬殺ワークもやりました。', 1, '2024-08-13 23:39:36', '2024-08-14 12:05:02'),
(918, 26, '2024-08-14', '1', '2', 'お手洗いに立つたびに、瞬殺ワークやったり、脇の下さすったりしました。呼吸ワークについては、常に肋骨を締めた状態で呼吸できるようになるのが理想ですか？', 1, '2024-08-14 23:18:48', '2024-08-15 18:29:38'),
(919, 26, '2024-08-16', '2', '2', 'おへその位置を後ろに下げようとすると重心も一緒に後ろにずれてしまいます。重心は真ん中のまま、お腹を引っ込めてまっすぐ立つ方法をもう一度教えてほしいです。', 1, '2024-08-17 01:22:18', '2024-08-20 22:13:44'),
(920, 26, '2024-08-19', '1', '2', '上半身から先に前に出すイメージで歩いてみました。普段よりどんどん前に前に進む感じで歩くんだなと思いました。', 1, '2024-08-20 08:36:35', '2024-08-20 22:13:59'),
(921, 26, '2024-08-20', '1', '2', '今日も上半身から前にを意識して歩きました。', 1, '2024-08-20 23:40:40', '2024-08-21 00:11:08'),
(922, 26, '2024-08-21', '2', '2', '今日は足の親指を地面から最後に離すのを意識して歩きました。明日は先ほど習った姿勢を意識してみます。', 1, '2024-08-21 22:52:16', '2024-08-21 22:54:17'),
(923, 26, '2024-08-22', '2', '2', '昨日のレッスンでやった、座り方と立ち方を意識しました。坐骨を立てると腰が反ってしまう感じがしたのですが、昨日習った立ち方と同じでおへそを後ろに移動させる感じで調整すれば良いでしょうか？', 1, '2024-08-22 23:57:08', '2024-08-23 12:33:23'),
(924, 26, '2024-08-24', '2', '2', '今日は歩いていて、いつもより立方骨を感じられた気がしました。', 1, '2024-08-25 00:02:16', '2024-08-25 00:25:35'),
(925, 26, '2024-08-26', '1', '2', '今日はいつもより、腋下の筋膜リリースが痛かったです。', 1, '2024-08-26 23:24:18', '2024-08-27 00:04:12'),
(926, 28, '2024-08-26', '3', '2', '寝落ちてしまいましたが瞬殺ワークだけはやれました。', 1, '2024-08-27 01:39:22', '2024-08-27 12:30:49'),
(927, 26, '2024-08-28', '1', '2', '昨日のレッスンでやった肩を下げるワークのやり方をもう一度教えてほしいです。', 1, '2024-08-28 23:59:20', '2024-09-02 08:38:05'),
(928, 28, '2024-08-25', '2', '2', '', 1, '2024-08-29 00:10:54', '2024-09-02 08:38:59'),
(929, 26, '2024-08-31', '1', '2', '息とめるのが、すぐ苦しくなってしまいます。何度もやるうちに、長く止められるようになるんでしょうか。', 1, '2024-08-31 23:53:02', '2024-09-02 08:38:11'),
(930, 28, '2024-08-31', '1', '1', '首のワークと仙骨ロック外しやりました', 1, '2024-09-01 13:09:29', '2024-09-02 08:38:56'),
(931, 26, '2024-09-01', '2', '2', '意識することが多すぎて、わけ分からなくなって来ました…', 1, '2024-09-02 00:25:23', '2024-09-02 08:38:26'),
(932, 26, '2024-09-03', '1', '2', '基本ワーク3つと呼吸ワーク、血糖値下げ下げワークをやりました。\r\n最近、少し中だるみしてたので、今日からまたしっかりワークやっていきます。', 1, '2024-09-03 23:17:53', '2024-09-03 23:28:55'),
(933, 26, '2024-09-05', '1', '2', 'かかとを一直線に歩くことを意識したら、左脚の股関節が痛くなりました。どうしたら良いですか？', 1, '2024-09-05 23:36:08', '2024-09-06 12:47:09');
INSERT INTO `daily_reports` (`id`, `user_id`, `report_date`, `status`, `intestine_status`, `comment`, `is_checked`, `created`, `modified`) VALUES
(934, 28, '2024-09-05', '2', '2', '昨日は瞬殺ワークはやりました。\r\n体がぐらつきやすいので体幹のワークもやろうと思います。', 1, '2024-09-06 09:21:52', '2024-09-06 12:42:25'),
(935, 28, '2024-09-09', '2', '2', '仙骨ロック外しと首を伸ばすワークと瞬殺ワークはやりました。明日は壁のやつもやります。', 1, '2024-09-10 00:10:31', '2024-09-10 09:54:34'),
(936, 28, '2024-09-26', '2', '2', '腹筋のワーク五回はやったのですが細かいところを忘れてしまったので動画を早めに貼っていただけると幸いです。\r\n仙骨ロック外しと瞬殺ワークはやりました！', 1, '2024-09-26 22:35:21', '2024-09-26 23:24:52'),
(937, 28, '2024-09-27', '2', '2', 'グループレッスン後腹筋を復讐がてら五回ずつやりました。多分覚えたと思います。\r\n明日もやります。', 1, '2024-09-28 00:13:51', '2024-09-28 00:36:11'),
(938, 28, '2024-09-30', '2', '2', '今のところ毎日腹筋のワークもできています。仙骨も、余裕がある時につま先立ちワークもしてます。最近はふくらはぎがむくむと言うより突っ張ってる感じがよくありますが立ち方の問題でしょうか？💦', 1, '2024-10-01 10:36:44', '2024-10-01 11:20:00'),
(939, 28, '2024-10-02', '2', '2', 'とりあえず腹筋は続いています。\r\n最近思ったのですが座ってる時は足は割と開いてる感じでいいのでしょうか？', 1, '2024-10-03 13:19:12', '2024-10-03 14:56:49'),
(940, 34, '2024-11-14', '1', '2', '動画123見た！ボールはまだないので、2をやってみたら、親指上がらず焦った(^^;;', 1, '2024-11-14 23:11:16', '2024-11-14 23:41:06'),
(941, 31, '2024-11-18', '1', '1', '今日、全身鏡が届いたので、膝の向きを確認しながらやりました。', 1, '2024-11-18 21:53:06', '2024-11-18 21:56:25'),
(942, 34, '2024-11-18', '2', '2', '距骨のワークは少しできました！今日写真撮って自分の写真に落ち込みました！頑張ろ！', 1, '2024-11-18 22:42:30', '2024-11-18 23:16:47'),
(943, 32, '2024-11-18', '1', '', '今日は 基本ワーク1と2をしました。\r\n今までに何回か、これをすると 腰が 少し痛くなってた感じだったのですが💦\r\n今日は大丈夫でした。', 1, '2024-11-18 23:14:24', '2024-11-18 23:16:03'),
(944, 32, '2024-11-19', '1', '', '今日実践したこと\r\n旧動画の講座 1 講座2 講座 3\r\n\r\n講座 1 と2をした後 やはり 腰が痛くなりました💦\r\nボールの位置のせいなのか？よくわかりませんが😩\r\n\r\n講座3（仙腸関節の緩み矯正）をした後\r\n1セット目は アフターに違いはそれほどなかったが 2セット目でアフターは\r\n座り心地が楽になった。ただ\r\n腰を左右に振った時以前からの痛みは まだ感じる💦', 1, '2024-11-19 16:06:23', '2024-11-19 22:04:39');
INSERT INTO `events` (`id`, `staff_id`, `title`, `type`, `content`, `start_datetime`, `end_datetime`, `created`, `modified`, `is_deleted`) VALUES
(1, NULL, 'オリエンテーション申込', '', '本プログラムの開始にあたって、3カ月間の基本的な流れと、\r\n効果的に進めるための運営方法やルールをご説明します。\r\n\r\n★下記の動画・資料を確認した上で、オリエンテーションをお申込みください。\r\n ※下記リンクをブラウザーへコピーして参照願います。\r\n\r\n１．オリエンテーション動画\r\nhttps://vimeo.com/850527488/dd24a44818\r\n\r\n２．オリエンテーション資料\r\nhttps://sites.google.com/view/shiryou/%E3%82%AA%E3%83%AA%E3%82%A8%E3%83%B3%E3%83%86%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E8%B3%87%E6%96%99', '2023-09-07 00:00:00', '2023-09-16 14:00:00', '2023-07-30 13:17:03', '2023-09-10 20:08:58', 0),
(2, 4, '目標設定コーチング申込', '2', '本プログラムで目指したい目標を担当講師よりコーチングし、最終的な目標KPIを設定します。\r\n※予約は初期診断の部位写真アップロード後、2営業日以降を目安に予約をしてください。\r\n※候補日時でご都合つかない場合は、[コミュニケーションツール]にて個別に講師と日程調整してください。', '2023-09-07 00:00:00', '2023-09-11 21:00:00', '2023-07-30 13:17:35', '2023-09-10 13:09:38', 0),
(3, NULL, '腸活コンサル申込', '2', '※腸活診断の結果が届いた方が申込対象です。\r\n解析センターから届いた診断結果をもとに腸内状況をご説明し、今後の腸活アプローチを決めていきます。', '2023-10-02 00:00:00', '2023-10-19 17:00:00', '2023-07-30 13:18:11', '2023-10-16 15:52:38', 0),
(4, 4, '最終カウンセリング申込（成果報告会）', '', '本プログラム終了時の美脚診断を行い、受講前と受講後で成果を確認する。\r\n併せて、プログラム終了後のアクションプランもカウンセリング。', '2023-10-23 00:00:00', '2023-10-26 09:23:00', '2023-07-30 13:19:11', '2023-10-27 09:23:04', 0),
(5, 4, 'グループレッスン申し込み（SHOCO先生）', '3', 'こちらよりグループレッスンの申し込みをお願いいたします。', '2023-09-25 00:00:00', NULL, '2023-07-31 22:14:25', '2024-11-20 11:47:55', 0),
(6, 4, '個別コンサル申し込み（YUMICO）', '2', '1回30分です\r\n進捗管理、不明点を解消します\r\n2回/月ご予約いただけます！\r\n\r\n※ご予定合わない方は [コミュニケーションツール] で個別にご相談ください。\r\n※原則、開催日の前日までに予約をお願いします。（※もし当日予約されたい場合は、事務局へ一報ください）', '2023-09-06 00:00:00', NULL, '2023-08-07 00:57:44', '2024-09-20 18:01:47', 0),
(7, 8, 'mail test', '2', 'mail [test](https://ashiyasebikyaku.com/admin/events/add)', '2024-02-23 17:58:00', '2024-02-28 17:58:00', '2024-02-24 17:59:35', '2024-02-24 17:59:35', 0),
(8, 8, 'イベント', '2', 'イベント', '2024-08-06 11:02:00', '2024-08-15 11:02:00', '2024-08-08 11:02:41', '2024-08-08 11:02:41', 0);
