INSERT INTO `informations` (`id`, `content`, `target`, `start_datetime`, `end_datetime`, `created`, `modified`, `is_deleted`) VALUES
(1, '■12月ご入会頂きました皆様へ\r\n⇒ご入会頂き誠に有難うございます。\r\n　皆さんの自己実現に向けスタッフ一同全力でサポートさせて頂きますので　\r\n　運用上で不明点やご質問等ある場合は、左記メニューの [コミュニケーションツール] よりご連絡ください。\r\n　講師もしくは事務局より、2営業日以内にご回答させて頂きます。', '1', '2023-11-28 15:31:00', '2023-12-09 23:59:00', '2023-07-30 18:12:45', '2023-11-29 12:08:14', 0),
(2, '【事務局からの連絡です】\r\n　8/21(月)に開催したグループレッスン動画をアップしましたので\r\n　左記メニュー [グループレッスン] からご参照頂けます。', '1', '2023-08-22 21:00:00', '2023-08-26 23:59:00', '2023-08-06 23:34:23', '2023-08-22 21:07:28', 1),
(3, '【事務局からの連絡です】\r\n　グループレッスン＆個人コンサルに関する９月分の申込開始しました。\r\n　ご希望の方は予約をお願いします。', '1', '2023-08-29 20:55:00', '2023-09-30 23:59:00', '2023-08-08 19:48:59', '2023-08-29 20:55:40', 0),
(4, '【事務局からの連絡です】\r\n　8/21(月)に開催したグループレッスン動画をアップしましたので\r\n　左記メニュー [グループレッスン] からご参照頂けます。', '1', '2023-08-22 21:00:00', '2023-08-26 23:59:00', '2023-08-22 21:06:57', '2023-08-22 21:07:08', 1),
(5, '【事務局からの連絡です】\r\n　8/21(月)に開催したグループレッスン動画をアップしましたので\r\n　左記メニュー [グループレッスン] からご参照頂けます。', '1', '2023-08-22 21:00:00', '2023-08-26 23:59:00', '2023-08-22 21:07:45', '2023-08-22 21:07:45', 0),
(6, '【事務局からの連絡です】\r\n　腸活の診断結果がご自宅に届いた方は、\r\n　パーソナルプログラム or イベント情報より\r\n         腸活コンサルをお申込みください。', '1', '2023-10-02 23:00:00', '2023-10-08 23:59:00', '2023-08-29 11:02:02', '2023-10-02 23:13:35', 0),
(7, '【事務局からの連絡】\r\n　10/16,23のグループレッスン動画をアップしました。\r\n　左記メニューの[グループレッスン]よりアクセスください。', '1', '2023-09-11 00:00:00', '2023-11-03 23:59:00', '2023-08-29 20:07:20', '2023-10-27 09:21:40', 0),
(8, 'SHOCO先生　個別コンサルティングの日程追加してますのでご予約ください！', '1', '2023-12-04 14:15:00', '2023-12-08 14:15:00', '2023-12-04 14:15:25', '2023-12-04 14:15:25', 0),
(9, '12月のグループレッスンの日程追加しました！', '1', '2023-12-04 14:15:00', '2023-12-08 14:15:00', '2023-12-04 14:15:56', '2023-12-04 14:15:56', 0),
(10, 'こんにちは！事務局です。今日は天気も悪いですね。しっかり足裏ほぐしていきましょう！また、最近寝不足の人は、身体の水分が足りなくなってるかも！最近やたらのどが渇くなーって場合は、みかんや豆腐、はまぐりなんかを取り入れてみてください！', '1', '2023-12-05 13:33:00', '2023-12-06 13:33:00', '2023-12-05 13:38:09', '2023-12-05 13:38:09', 0),
(11, 'おはようございます。事務局です。今日は暖かいですね！寒暖差で身体が疲れてしまわないように、今日はしっかり足指のストレッチも行いましょう！また冬は冷えによって腎臓が疲れやすくなります。腎臓には黒ゴマや黒豆のような黒い食材やお豆腐などが良いです。今日の食材に取り入れてみてください！', '1', '2023-12-06 09:50:00', '2023-12-07 09:50:00', '2023-12-06 10:09:53', '2023-12-06 10:09:53', 0),
(12, 'こんにちは！事務局です！今日もあたたかいですね。寒暖差で体調崩しやすくなりますので、体温管理も気を付けましょうね！\r\nこの時期は首肩が固まりやすくなってくるので、いつもより自分の首の位置を気にするようにしましょう！内臓が弱ってるなーって方は、山芋をとってみてくださいね！', '1', '2023-12-07 14:35:00', '2023-12-08 14:35:00', '2023-12-07 14:39:06', '2023-12-07 14:39:06', 0),
(13, 'おはようございます！朝、のど痛いなーって方いませんか？もしかすると睡眠中に口呼吸になってるかも！試しにお口にテープを貼って寝てみてください。朝喉痛くないーって方は、口呼吸になってる可能性大ですよ。口呼吸になると免疫下がったり、横隔膜が動かなくなって痩せにくくなりますよ！日中はむずかしいと思うので、寝てる時に試してみてください。さー！今日もO脚瞬殺ワークやって、緩めていきましょう！', '1', '2023-12-08 10:42:00', '2023-12-09 10:43:00', '2023-12-08 10:52:35', '2023-12-08 10:52:35', 0),
(14, 'おはようございます！事務局です。今日は関東はお出かけ日和ですね！寒暖差に気を付けてお過ごしください！お出かけする方も、しない方も、今日は脚をまっすぐ出す、ことを意識してみてください。つま先、くるぶしの内側、膝の内側、股関節を一直線に置いて出す、ことです。鏡でチェックできる方は鏡チェックも必須です。座ってる時、立ってる時、歩いてる時、自分の脚がどんなふうに置かれてるか、出されてるかをチェックしてみましょう！そして改めて、つま先はどこ？くるぶしの内側はどこ？膝の内側はどこ？股関節はどこ？指差し確認しましょう。ボディマッピングですね！脳内イメージで身体は大きく変わります。脳内のイメージを正しいものにして、美脚を加速しましょう！', '1', '2023-12-09 10:23:00', '2023-12-10 10:23:00', '2023-12-09 10:30:04', '2023-12-09 10:30:04', 0),
(15, 'おはようございます。いよいよ年末ですね。今日も瞬殺ワークで身体を起こしていきましょう。さらに今日は腕を正しく上げ下げしてみましょう。年末はやることたくさんで首肩が凝りやすくなっていきます。腕の上げ下げで肩甲骨を動かす感覚をつかんでみましょうね。そして、やることたくさんであわただしいー、なんてことでストレスため込んでませんか？そんな時はホウレンソウを食べてみてください！お鍋とかスープとか温かい調理法がおすすめです', '1', '2023-12-10 10:09:00', '2023-12-11 10:09:00', '2023-12-10 10:12:27', '2023-12-10 10:12:27', 0),
(16, 'おはようございます。今日は肋骨と背骨を意識してみましょう！頭の上で手を組んで、肋骨だけを上げ下げしたり、肋骨ぱっかんとならないように、後ろから手のひらで肋骨をこする、ことを気づいたらやってみましょう！最近少し暖かいですが、身体は知らずのうちに冷えてることあります。瞬殺ワークでしっかり身体を目覚めさせることと、それでも冷えるなーってときは「はちみつ」とってみましょう！', '1', '2023-12-11 10:33:00', '2023-12-12 10:33:00', '2023-12-11 10:39:45', '2023-12-11 10:39:45', 0),
(17, 'こんにちは！事務局です。今日は関東は曇りでした。気圧変化苦手な人は、ちょっとしんどかったでしょうか？そんなときは、自律神経が乱れがちかも。仙骨から背骨を整えていきましょう！体育すわりして、前後にゴロンゴロンと転がるだけでも、背骨回りの神経が刺激されて自律神経が整います！寝る前にやってみてください！また、胃が疲れたなーって人は、薬膳界のスーパーフード！山芋がおすすめです！山芋はまとめて切ったりすりおろしたりして、冷凍しておくと、日々使いやすくなります！', '1', '2023-12-12 20:41:00', '2023-12-13 20:41:00', '2023-12-12 20:41:09', '2023-12-12 20:41:09', 0),
(18, 'おはようございます！事務局です。来週からは寒くなるようですね。しっかり、足首から下を整えていきましょう！距骨調整と足指マッサージは午前中に1回はやっておきましょう！（やる前、やった後とで感覚がどう変わるかのチェックもしてみてください）。なんだか最近やる気でないなーとか、元気ないなーって方は「しらす」おすすめです。しらすは、腎臓肝臓の元気を取り戻してくれます。（胃腸弱い方は食べすぎには注意です！）', '1', '2023-12-13 09:47:00', '2023-12-14 09:47:00', '2023-12-13 09:51:30', '2023-12-13 09:51:30', 0),
(19, 'こんにちは！事務局です。しっかり睡眠取れてますか？今日は呼吸を意識してみましょう！呼吸で大切なのは吐く方です。実は現代人は息を吐き切れてなくて、吸いすぎることで、呼吸が浅くなっていたりします。深呼吸をするときは、とにかく吐ききる、ことをやってみましょう。もうこれ以上吐けないーからさらに2秒長く吐いてみる、をやってみてください。そして、今日の食材は玉ねぎです！なんだか身体のめぐりが悪いわーって方は玉ねぎが巡りをサポートしてくれるのでお勧めです。あと便秘気味な方も、玉ねぎにはオリゴ糖が含まれてて腸にも良いので取り入れてみてください', '1', '2023-12-14 10:28:00', '2023-12-15 10:28:00', '2023-12-14 10:50:03', '2023-12-14 10:50:03', 0),
(20, 'おはようございます！12月も半分過ぎました！年末に向けてラストスパート頑張っていきましょう！今日は先日のグループレッスンであったように音を立てないで歩く、階段をかかとからのぼる（かかとを階段の外に出したりするのは絶対ＮＧ！！）をやってみましょう！かかとで着地して、股関節を使う、ことを意識ですよ！\r\nそして今日の食材はうなぎ、です。ウナギはなんだかやる気が出ないー、ってときに気をめぐらすのに有効ですよ！', '1', '2023-12-15 09:16:00', '2023-12-16 09:16:00', '2023-12-15 10:03:47', '2023-12-15 10:03:47', 0),
(21, 'こんにちは！事務局です。インフルエンザ流行ってますね！関節ワークで、どなたも感染してないと聞いてますが、更に免疫高めるように強化していきましょう！インフルエンザにかかりにくい人は唾液が多い人って言われてます。しかもその唾液は顎の下から出る唾液です。口が渇くなーみたいなときは、顎下を軽く押して唾液を出してあげるようにしましょう！！そして今日の食材は、三つ葉です。睡眠が足りないなーとか、イライラしやすいなーってときは、気のめぐりが滞ってます。そんな時は香りのある食材がおすすめです。卵とじとかおすすめです！', '1', '2023-12-16 13:00:00', '2023-12-17 13:00:00', '2023-12-16 13:08:20', '2023-12-16 13:08:20', 0),
(22, 'こんにちは！事務局です！\r\nみなさん、日次報告してますか？？お待ちしてますので、ぜひ１日一度はサイトをご覧になったり、今日の自分を振り返ることをしてみましょう！！', '1', '2023-12-21 18:04:00', '2023-12-22 18:04:00', '2023-12-21 18:05:36', '2023-12-21 18:05:36', 0),
(23, 'こんにちは！今日はイブイブですね！おいしい物を食べる方もいらっしゃるかもですね！！食べる時は、食事の量やバランスなんかも大切ですが、結構重要なのは噛む回数！郷ひろみも若さの秘訣はよく噛むこと！って言ってます（笑）毎回30回は難しくても、最初の一口だけ意識して噛むだけでも大丈夫です。あとは、一口ごとに箸をおきましょう。これで早食いが避けられますよ。\r\n噛むメリットは■唾液が分泌され消化しやすくなる（唾液は殺菌効果もあり免疫もあげてくれます）■噛むことで脳内へ刺激が行き脳が活性化される（頭蓋骨にある天才の骨「蝶形骨」って骨を刺激してくれます）■小顔になる　などなどたくさんあります！今日はハイカロリーなもの食べるなーとか、たくさん食べるなーって日は、噛む回数を意識してみましょう！', '1', '2023-12-23 11:56:00', '2023-12-24 11:56:00', '2023-12-23 12:06:00', '2023-12-23 12:06:00', 0),
(24, 'こんにちは！事務局です。1月のグループレッスンの日程が決まりました！ご予約お待ちしてます！', '1', '2023-12-28 18:34:00', '2023-12-31 18:34:00', '2023-12-28 18:35:32', '2023-12-28 18:35:32', 0),
(25, '新年あけましておめでとうございます！本年も美脚に向けて頑張っていきましょう！！！', '1', '2024-01-01 18:13:00', '2024-01-03 18:14:00', '2024-01-01 18:15:13', '2024-01-01 18:15:13', 0),
(26, '石川で大きな地震が発生しておりますが、皆様安全確保はできてますでしょうか？？', '1', '2024-01-01 18:15:00', '2024-01-03 18:15:00', '2024-01-01 18:16:34', '2024-01-01 18:16:34', 0),
(27, '1月のSHOCO先生の個別コンサルの日程アップしてますので、ご予約くださいませ！', '1', '2024-01-02 15:22:00', '2024-01-03 15:22:00', '2024-01-02 15:23:07', '2024-01-02 15:23:07', 0),
(28, '1/31のSHOCO先生のグループレッスン動画をアップしてますので、ご活用くださいませ！', '1', '2024-02-04 21:05:00', '2024-02-11 21:06:00', '2024-02-04 21:06:07', '2024-02-04 21:06:07', 0),
(29, 'こんにちは！2月のグループレッスンのテーマはコチラです。ご予約お待ちしてます！\r\n\r\n■2月7日（水）21時～　肋骨、鎖骨を動かして肩こり解消\r\n■2月14日（水）21時～　歩き方改善\r\n■2月21日（水）21時～　腰を使わない身体の使い方', '1', '2024-02-06 09:58:00', '2024-02-29 09:58:00', '2024-02-06 09:58:54', '2024-02-06 09:58:54', 0),
(30, 'SHOCO先生の個別コンサルもご予約お待ちしてます！', '1', '2024-02-04 11:51:00', '2024-02-10 11:51:00', '2024-02-06 11:51:45', '2024-02-06 11:51:45', 0),
(31, 'こんにちは！３月のグループレッスン動画を登録しました。\r\n参加できなかった方は、是非ご参照頂いて自己ワークに活用ください。', '1', '2024-03-20 17:01:00', '2024-03-31 17:01:00', '2024-03-20 17:01:19', '2024-03-20 17:01:19', 0),
(32, 'GW如何お過ごしでしょうか？\r\n\r\n急遽、5/1,2の個人コンサル枠をご用意させて頂きましたので\r\nよければご予約いただければと思います。\r\n\r\nPS.  4/25のグループレッスン動画もアップしましたので、\r\n        GWで疲れたカラダを緩めてみてください！', '1', '2024-05-01 13:50:00', '2024-05-02 23:59:00', '2024-05-01 13:50:41', '2024-05-01 13:55:48', 0),
(33, 'GW後半は夏日のような暑い日が続いてますが、如何お過ごしでしょうか！\r\n\r\n5月の「グループワーク」と「個別コンサル」の候補日を登録しました。\r\nGWで遊び疲れたカラダを緩めて頂ければと思いますので\r\nご予約の程、よろしくお願いいたします。\r\n\r\n[【グループワーク】](https://ashiyasebikyaku.com/mypage/events/view/5)　←こちらから予約できます\r\n[【個別コンサル】](https://ashiyasebikyaku.com/mypage/events/view/6)　←こちらから予約できます', '1', '2024-05-04 18:22:00', '2024-05-31 23:59:00', '2024-05-04 18:24:49', '2024-05-04 18:32:47', 0),
(34, '5/8グループレッスン動画をアップしました！\r\n今回のテーマは、「立ち方」', '1', '2024-05-10 14:35:00', '2024-05-18 14:35:00', '2024-05-10 14:35:16', '2024-05-10 14:35:16', 0),
(35, '個人コンサルの5月スケジュールを追加しました。\r\n日々ワークでのお悩み相談やQ&A等、上手く活用頂ければと思います。\r\n\r\n【追加日程】：5/22(水), 5/23((木)), 5/24(金), 5/29(水), 5/30(木), 5/31(金)\r\n\r\n[【グループワーク】](https://ashiyasebikyaku.com/mypage/events/view/5)　←5月分の枠空いてます\r\n[【個別コンサル】](https://ashiyasebikyaku.com/mypage/events/view/6)　←こちらから予約ください', '1', '2024-05-21 12:13:00', '2024-05-31 20:59:00', '2024-05-21 12:13:59', '2024-05-21 12:13:59', 0),
(36, '6月後半のコンサル日程を入れましたのでご予約お待ちしております！', '1', '2024-06-14 18:40:00', '2024-06-21 18:40:00', '2024-06-14 18:41:21', '2024-06-14 18:41:21', 0);
