(7, '2023.08.06_グループレッスン（膝と足首、股関節を連動させる。仙骨肋骨首を緩める）', '/uploads/lesson_movie/7/78964ae7ba96827f358eed44e98f5825294cc1851691330181.jpg', 'https://player.vimeo.com/video/852072737?h=33dfb6a3bf', '【こんな方におススメ】\r\n　・STEP1を始めてみて  \"脱力\"  が難しいなと感じている方\r\n【実施ワーク】\r\n　①膝・足首・股関節を連動させて緩める\r\n　②仙骨・助骨・首をそれぞれ緩める', '2023-08-06 22:56:21', '2023-10-10 23:09:35', 0, 0),
(8, '2023.08.21_グループレッスン（距骨、仙骨、股関節の動きを感じる、鎖骨、肋骨の動きを感じる）', '/uploads/lesson_movie/8/78964ae7ba96827f358eed44e98f5825294cc1851692705851.jpg', 'https://player.vimeo.com/video/856597158?h=f3eb85bd31', '【こんな方におススメ】\r\n　・関節にちゃんと当てれているか不安な方\r\n【実施ワーク】\r\n　①距骨・仙骨・股関節の動きを感じて緊張をとる\r\n　②鎖骨、肋骨の動きを感じて緊張をとる', '2023-08-22 21:04:11', '2023-10-10 23:08:38', 0, 0),
(9, '2023.08.28_グループレッスン（距骨のはめ込みと仙腸関節を整えて全身の緊張を取る）', '/uploads/lesson_movie/9/78964ae7ba96827f358eed44e98f5825294cc1851693307061.jpg', 'https://player.vimeo.com/video/858934724?h=4f8e32f63a', '【こんな方におススメ】\r\n　・股関節の動きを改善したい方\r\n【実施ワーク】\r\n　①股関節の可動域を広げる\r\n　②上半身（肋骨・頸椎）の緊張を取る', '2023-08-29 20:04:21', '2023-11-24 22:53:59', 0, 0),
(10, '2023.09.04_グループレッスン（仙腸関節～背骨～頸椎を動かす）', '/uploads/lesson_movie/10/78964ae7ba96827f358eed44e98f5825294cc1851693956327.jpg', 'https://player.vimeo.com/video/861099835?h=085851d5e4', '【こんな方におススメ】\r\n　・腰痛がある時　腰のバランスを戻したい方\r\n【実施ワーク】\r\n　①仙腸関節～背骨～頸椎を動かす', '2023-09-06 08:23:44', '2023-10-10 23:10:42', 0, 0),
(11, '2023.09.10_グループレッスン（足首（距骨）～股関節をいろんな方向に動かす）', '/uploads/lesson_movie/11/78964ae7ba96827f358eed44e98f5825294cc1851694395515.jpg', 'https://player.vimeo.com/video/862996148?h=0ae88cb82d', '【こんな方におススメ】\r\n　・距骨が見つからない方\r\n　・股関節の可動域を広げたい方\r\n【実施ワーク】\r\n　①距骨探し\r\n　②股関節を色んな方向に動かす', '2023-09-11 10:25:15', '2023-10-10 23:11:18', 0, 0),
(12, '2023.09.18_グループレッスン（足指　足裏を使う）', '/uploads/lesson_movie/12/78964ae7ba96827f358eed44e98f5825294cc1851696634381.jpg', 'https://player.vimeo.com/video/865831767?h=f60ae1da0a', '【こんな方におススメ】\r\n　・足指・足裏アーチが思うように使えてない方\r\n　・足指グーができない方\r\n【実施ワーク】\r\n　①足指強化ワーク\r\n　②足裏アーチ強化ワーク', '2023-10-07 08:19:41', '2023-10-10 23:11:47', 0, 0),
(13, '2023.10.09_グループワーク（足裏・足指から美脚を整える）', '/uploads/lesson_movie/13/78964ae7ba96827f358eed44e98f5825294cc1851696946797.jpg', 'https://player.vimeo.com/video/872845805?h=5312ffd124', '【こんな方におススメ】\r\n　・足指・足裏アーチが思うように使えてない方\r\n　・ふくらはぎパンパンな方\r\n　・前モモパンパンな方\r\n　・股関節が動かない方\r\n【実施ワーク】\r\n　①足裏強化ワーク\r\n　②股関節ゆるゆるワーク\r\n　③O脚瞬殺ワーク', '2023-10-10 23:06:37', '2023-10-10 23:12:17', 0, 0),
(14, '20231016_グループワーク（脚を真っすぐ使う））', '/uploads/lesson_movie/14/78964ae7ba96827f358eed44e98f5825294cc1851698364576.jpg', 'https://player.vimeo.com/video/877846624?h=832163b802', 'こんな方におススメ】\r\n　・脚がまっすぐ使えない方\r\n　・股関節に固さを感じてる方\r\n【実施ワーク】\r\n　①脚を真っすぐ使うワーク\r\n　②股関節ゆるゆるワーク', '2023-10-27 08:56:16', '2023-10-27 09:00:46', 0, 0),
(15, '20231023_グループワーク（内もものお肉をとる）', '/uploads/lesson_movie/15/78964ae7ba96827f358eed44e98f5825294cc1851698364747.jpg', 'https://player.vimeo.com/video/877829684?h=755078e712', '【こんな方におススメ】\r\n　・立ったり歩いたりの時に内もも使えてない方\r\n　・外モモの張りが強い方\r\n【実施ワーク】\r\n　①足首の固さをとるワーク\r\n　②足裏を均等に踏むワーク\r\n　③内側キックワーク\r\n　④X立ち、内股立ちで内もも締めるワーク', '2023-10-27 08:59:07', '2023-10-27 09:02:18', 0, 0),
(16, '20231106_グループレッスン_足指強化', '/uploads/lesson_movie/16/78964ae7ba96827f358eed44e98f5825294cc1851700035480.jpg', 'https://player.vimeo.com/video/883653369?h=37a45d13dc', '【こんな方におススメ】\r\n　・足裏、足指を強化したい方\r\n　・足裏がかたい方\r\n\r\n【実施ワーク】\r\n　①足指ワーク\r\n　②脚を内側からまっすぐ出すワーク\r\n　③足指の母指球で踏むワーク\r\n　④前モモ伸ばすワーク', '2023-11-15 17:04:40', '2023-11-24 22:53:10', 0, 0),
(17, '20231113_グループレッスン_立ち方', '/uploads/lesson_movie/17/78964ae7ba96827f358eed44e98f5825294cc1851700438042.jpg', 'https://player.vimeo.com/video/884870516?h=18eab66512', 'こんな方におススメ】\r\n　・重心チェックしたい方\r\n　・骨盤が動いてない方\r\n　・仙骨立ってない方\r\n\r\n【実施ワーク】\r\n　①重心調整ワーク\r\n　②骨盤動かすワーク', '2023-11-20 08:53:48', '2023-11-24 22:53:02', 0, 0),
(18, '20231120_グループレッスン_骨盤と肋骨', '/uploads/lesson_movie/18/78964ae7ba96827f358eed44e98f5825294cc1851700833954.jpg', 'https://player.vimeo.com/video/887956060?h=3e0b781d38', '【こんな方におススメ】\r\n　・骨盤が動かない方\r\n　・肋骨まわりがかたい方\r\n\r\n【実施ワーク】\r\n　①骨盤を前後に動かすワーク\r\n　②肋骨を動かすワーク\r\n　③股関節動かすワーク\r\n　④呼吸のワーク', '2023-11-24 22:51:56', '2023-11-24 22:52:34', 0, 0),
(19, '20231213_グループレッスン_背中を使う', '/uploads/lesson_movie/19/78964ae7ba96827f358eed44e98f5825294cc1851702784479.jpg', 'https://player.vimeo.com/video/895417216?h=26714947ad', '【こんな方におススメ】\r\n　・股関節がかたい方\r\n　・上半身が使えてないと感じる方\r\n【実施ワーク】\r\n　①股関節はめるワーク\r\n　②肩甲骨動かすワーク\r\n　③背中を使った肩位置の調整ワーク', '2023-12-17 12:41:19', '2023-12-17 12:42:06', 0, 0),
