(54, '20240827  背骨から首を緩めて小顔にする', '/uploads/lesson_movie/54/51e63f4747e4c201f96abefc1d08e4a2b59a64071725354341.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724812530_20240827%E3%80%80%E8%83%8C%E9%AA%A8%E3%81%8B%E3%82%89%E9%A6%96%E3%82%92%E7%B7%A9%E3%82%81%E3%81%A6%E5%B0%8F%E9%A1%94%E3%81%AB%E3%81%99%E3%82%8B.mp4', '【こんな方にお勧め】\r\n■顔をすっきりさせたい方\r\n■ストレートネックが気になる方\r\n\r\n【実施ワーク】\r\n■ビフォーチェック\r\n■瞬殺ワーク\r\n■膝抱っこで背骨の緊張をとる\r\n■肋骨を動かして背骨を緩める\r\n■首をのばす\r\n■アフターチェック', '2024-08-28 11:36:17', '2024-09-03 18:05:41', 0, 0),
(55, '20240823 ウォーキング', '/uploads/lesson_movie/55/2e919aeea95f734edd21f09f117c1867c0abb7e11725354327.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724813129_20240823%E3%80%80%E3%82%A6%E3%82%A9%E3%83%BC%E3%82%AD%E3%83%B3%E3%82%B0.mp4', '【こんな方にお勧め】\r\n■歩くだけで美脚になりたい方\r\n■足首がかたくて脚のローリングがうまくいかない方\r\n\r\n【実施ワーク】\r\n■アキレス腱ほぐし\r\n■距骨はめ\r\n■立方骨ペンワーク\r\n■スネ位置調整', '2024-08-28 11:46:13', '2024-09-03 18:05:27', 0, 0),
(56, '20240821 坐骨を立てる座り方', '/uploads/lesson_movie/56/659ec04b5e8f930bbfdb483f3fae7974141e2bf41725354314.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724815909_20240821%E5%9D%90%E9%AA%A8%E3%82%92%E7%AB%8B%E3%81%A6%E3%82%8B%E5%BA%A7%E3%82%8A%E6%96%B9.mp4', '【こんな方にお勧め】\r\n■座り時間が長い方\r\n■骨盤立て方が分からない方\r\n\r\n【実施ワーク】\r\n■坐骨のボディーマッピング\r\n■坐骨を動かすワーク\r\n■立ち方\r\n', '2024-08-28 12:32:13', '2024-09-03 18:05:14', 0, 0),
(57, '20240816 ウォーキング', '/uploads/lesson_movie/57/dee5f35224792c0ae9f49be5bbff2746e3a286981725354302.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724818215_20240816%E3%80%80%E3%82%A6%E3%82%A9%E3%83%BC%E3%82%AD%E3%83%B3%E3%82%B0.mp4', '【こんな方にお勧め】\r\n■歩くだけで美脚になりたい方\r\n■上半身の位置が定まらず脚に負担がある方\r\n■股関節がかたい方\r\n\r\n【実施ワーク】\r\n■瞬殺ワーク\r\n■肩下げワーク\r\n■肩甲骨動かすワーク\r\n■骨盤と上半身を一緒に動かすワーク', '2024-08-28 13:12:05', '2024-09-03 18:05:02', 0, 0),
(58, '20240815 血糖値下げ下げワーク（ハード版）', '/uploads/lesson_movie/58/9e6d942fc05a0b3e0bfcd7d84cb72d8e195ea4d61725354287.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724818874_20240815%E3%80%80%E8%A1%80%E7%B3%96%E5%80%A4%E4%B8%8B%E3%81%92%E4%B8%8B%E3%81%92%E3%83%AF%E3%83%BC%E3%82%AF.mp4', '【こんな方にお勧め】\r\n■体重、体脂肪率下げたい方\r\n■食べた後眠くなっちゃう方\r\n\r\n【実施ワーク】\r\n■瞬殺ワーク\r\n■下げ下げワーク（ソフト版）\r\n■呼吸と腹圧\r\n■立ち方', '2024-08-28 13:22:29', '2024-09-03 18:04:47', 0, 0),
(59, '20240809 ウォーキング', '/uploads/lesson_movie/59/1884a2ee2f729345ae80e6ca965902b74042c6691725354274.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724819865_20240809%E3%80%80%E3%82%A6%E3%82%A9%E3%83%BC%E3%82%AD%E3%83%B3%E3%82%B0.mp4', '【こんな方にお勧め】\r\n■歩くだけで美脚になりたい方\r\n■足首かたい方\r\n\r\n【実施ワーク】\r\n■瞬殺ワーク\r\n■足首強化ワーク', '2024-08-28 13:38:08', '2024-09-03 18:04:34', 0, 0),
(60, '20240807 脚が細くなる立ち方', '/uploads/lesson_movie/60/b3d13cecef9f8c6dc07f5d6fd3282187d4382f421725354242.png', 'https://ashiyasebikyaku.com/uploads/upload_movie/1724820028_20240807%E3%80%80%E8%84%9A%E3%81%8C%E7%B4%B0%E3%81%8F%E3%81%AA%E3%82%8B%E7%AB%8B%E3%81%A1%E6%96%B9.mp4', '【こんな方にお勧め】\r\n■立ってるだけでしんどい方\r\n■細くなる立ち方を習得したい方\r\n\r\n【実施ワーク】\r\n■呼吸で腹圧入れる\r\n■距骨はめワーク\r\n■スネと膝をそろえるワーク\r\n■立ち方ワーク\r\n■股関節ツルンツルン', '2024-08-28 13:41:16', '2024-09-03 18:04:02', 0, 0),
