(278, 3, 4, '長々とすみませんが、自分の備忘録としても残しておきたかったので色々コメントさせていただきました！引き続きよろしくお願いします☺️', '1', 1, '2023-09-11 20:52:05', '2023-09-11 20:52:05', 0),
(279, 2, 4, '今週のワーク更新しています。\r\n今回から新たに加えたクラムシェルと講座19のヤンキー座りは木曜日のコンサルまでに最低一回ずつはやってみてください。軽くでもOKです。\r\nそして、コンサルの時にご感想いただけたらと思います😊\r\nよろしくお願いいたします❣️', '2', 1, '2023-09-11 23:14:21', '2023-09-11 23:14:21', 0),
(280, 6, 4, 'りおさん、コンサルお疲れさまでした😊\r\n胸椎、肋骨のワークプラスしました。謎の背中の痛み…このワークでよくなるといいな🙏\r\nまた、感想お聞かせくださいね💜', '2', 1, '2023-09-11 23:23:48', '2023-09-11 23:23:48', 0),
(281, 3, 4, '原田さん、こんばんは😊\r\n\r\nそうなんです。体重よりも見た目なんです。ウエストや足が細っそりしていればお尻や胸が大きくても逆にスタイル良〜と感じますもんね😊\r\n\r\n歩き方に役に立ちそうなワーク、プラスしてます。合わせてやってみてくださいねー👍\r\n嬉しいご報告！ありがとうございました😆', '2', 1, '2023-09-11 23:36:19', '2023-09-11 23:36:19', 0),
(282, 6, 4, 'そーだ。\r\n今日のコンサル1時間取ってくださってたんですねー！ごめんなさい🙏通常のコンサルの時間で終わってしまいました💦残りの時間でレッスンすれば良かったですね💦🙏すみません。\r\nリクエストくださればいつでもコンサルの時間使ってレッスンできますので遠慮なく言ってくださいね。すみませんでした😓🙏', '2', 1, '2023-09-11 23:47:18', '2023-09-11 23:47:18', 0),
(283, 5, 4, 'しずかさん、おはようございます☀️\r\n\r\nうーん。やっぱりお尻の筋肉動かすとまだ腰痛が出るようですね…😓しばらくは緩める系ワーク中心でメニュー組みますね💨ストレッチ！お願いしますっ🥺', '2', 1, '2023-09-12 09:03:14', '2023-09-12 09:03:14', 0),
(284, 5, 4, 'SHOCOさん、おはようございます！\r\nあ、、、昨日は腰痛ではなく、腹痛で苦しんでおりました🥲腰痛は大丈夫です！\r\nご配慮くださりありがとうございます😭✨', '1', 1, '2023-09-12 10:53:20', '2023-09-12 10:53:20', 0),
(285, 6, 4, 'ありがとうございます！\r\n個別コンサルの件大丈夫です！\r\nまた時間のある時に入れさせて頂きます☺️', '1', 1, '2023-09-12 19:28:17', '2023-09-12 19:28:17', 0),
(286, 5, 4, 'しずかさん、こんにちは😊\r\nあっ！頭痛かぁ〜😆失礼しましたー💦💦でも、頭痛もしんどいね🥲ほんと、何もしたくなくなる😓そーゆー時はのんびりしててください😊', '2', 1, '2023-09-13 11:50:00', '2023-09-13 11:50:00', 0),
(287, 5, 4, '週次報告ありがとうございました✨✨\r\n体脂肪率減ってきてますね👍\r\n足首が増えてたのが😱でしたが、足指が使えてくると減るでしょう。と、言うことでグー✊のできる足指ですよぉ💨頑張りましょうね😄', '2', 1, '2023-09-13 11:51:58', '2023-09-13 11:51:58', 0),
(288, 2, 4, '保木さん、こんにちは😊\r\n苦手なところね。そうなんです。そろそろ動かしていただこうかな？と。\r\nでも。無理に使ったら効きすぎても筋肉疲労してしまうのでそのあたり、今日のコンサルで考えていきましょう！よろしくお願いいたします❣️', '2', 1, '2023-09-13 11:54:57', '2023-09-13 11:54:57', 0);
INSERT INTO `messages` (`id`, `user_id`, `staff_id`, `message`, `sender`, `is_read`, `created`, `modified`, `is_deleted`) VALUES
(289, 5, 4, 'こんにちは！\r\n足首増えてたのは完全にむくみです🥹仕事から帰ってきてすぐ測ったので🥹\r\n足首もですが、個人的にはお腹を何とかへこませたいです😭\r\n足指グーもがんばります！🔥', '1', 1, '2023-09-13 15:27:35', '2023-09-13 15:27:35', 0),
(290, 2, 4, 'いつもありがとうございます！\r\nコンサルは、明日の木曜日ですよね？今日は水曜日なので、明日、よろしくお願いいたします！', '1', 1, '2023-09-13 16:40:54', '2023-09-13 16:40:54', 0),
(291, 7, 4, '樹里さーん！\r\nごめんなさい🙏私の方のWi-Fiが調子悪くて繋がってなかったのですが〜💦💦大丈夫ですか？入れますか？', '2', 1, '2023-09-13 20:04:50', '2023-09-13 20:04:50', 0),
(292, 7, 4, '樹里さん。ごめんなさい🙏\r\n私、今日と勘違いしてました〜🙏🙏\r\n明日、よろしくお願いいたします🙇‍♀️', '2', 1, '2023-09-13 20:11:12', '2023-09-13 20:11:12', 0),
(293, 7, 4, 'こんばんは！メッセージ気づかずすみません🙇‍♀️\r\n木曜日に予約しました！よろしくお願いいたします！', '1', 1, '2023-09-14 00:51:44', '2023-09-14 00:51:44', 0),
(294, 7, 4, 'いえいえ。\r\n私の勘違いで昨日は1人で焦ってました😓🙏\r\nでは、今夜！よろしくお願いいたします😊\r\nzoomのIDは先日の目標設定の時と同じです！', '2', 1, '2023-09-14 11:27:22', '2023-09-14 11:27:22', 0),
(295, 5, 4, 'しずかさん、こんにちは😊\r\n浮腫〜💦💦同じ姿勢が続くと仕方がないんだけどねー。なので1日に最低1回はリセット！ですね😊\r\n\r\nお腹はまず❗️姿勢を整えた時に下腹にチカラが入ってる感覚があるか？から初めてみましょう😊無理にお腹引っ込めてチカラ入れておくのではなく、自然にお腹ぎ感じられるところで姿勢をつくるです。\r\n今夜のコンサルの時に少し練習してみましょう❗️よろしくお願いいたします😊', '2', 1, '2023-09-14 11:39:50', '2023-09-14 11:39:50', 0),
(296, 2, 4, '保木さん、こんにちは😊\r\n\r\nえへへ😅はい。私。また1日間違ってました💦今夜！です😅\r\n\r\n浮腫んでいる状態ぎわかってきたー❗️すごい✨✨慢性化しているとなかなか気づきにくいですね…😓\r\n\r\nワークでこまめにリセットしてそして更にはむくみにくい足を作りたいですね！\r\nでは、後ほどです😊\r\nよろしくお願いいたします✨', '2', 1, '2023-09-14 11:45:23', '2023-09-14 11:45:23', 0),
(297, 5, 4, 'お返事ありがとうございます！\r\nわかりました✨\r\nコンサルもよろしくお願いいたします🙇‍♀️✨', '1', 1, '2023-09-14 20:35:21', '2023-09-14 20:35:21', 0),
(298, 5, 4, 'しずかさん！ごめんなさい🙏\r\n入ってきてくださーい！', '2', 1, '2023-09-14 21:03:29', '2023-09-14 21:03:29', 0),
(299, 2, 4, '保木さん！\r\nコンサルお疲れさまでした😊\r\n\r\n今回ひとつお伺いしようと思ってたこと！聞き忘れました💦\r\n目標設定。変えなくてもいいですか？\r\n折り返し地点に来て新たな目標ができたり、もっと上を目指したくなったり…もしもありましたらゴールを変えようかと思います。いかがでしょうか⁉️', '2', 1, '2023-09-14 21:39:40', '2023-09-14 21:39:40', 0),
(300, 2, 4, '昨夜はありがとうございました!\r\n昨日はコンサルで聞きたいことが、いっぱいあって30分では足りなくて、すみません！\r\n目標設定は変えずにいきたいです。本当にこれがわたしの30年来の悩みなんです！現状みてやっぱり無謀でしょうか？確かに膝上から太ももの中間部分は細くなってきたので、足全体のバランスをみると美脚に近づいていると言えなくはないのですが、うち太もものぷにぷにが足太いなを実感せずにいられません。妥協するもしくは視点を変える方が良いでしょうか？', '1', 1, '2023-09-15 09:52:58', '2023-09-15 09:52:58', 0),
(301, 2, 4, '引き継ぎ質問です。\r\n基本のワークは、なるべく家で寝起きや寝る前にやりたいので、\r\n13-1の呼吸のワークは、仕事前や休憩の時間に椅子の上でやってみてもいいでしょうか？\r\n11-1のトレーニング系とか昨夜のコンサルでのハーフスクワットなら仕事の隙間時間に出来そうだなと思うのですが、そんなやり方でもいいでしょうか？', '1', 1, '2023-09-15 09:58:52', '2023-09-15 09:58:52', 0),
(302, 7, 4, 'こんばんは！\r\n昨日の個別コンサルありがとうございました☺️\r\n早速、腕の動きや隙間時間のワークやっています！\r\n昨日は毎日のワークもしっかり取り組めました！\r\nまた個別コンサル受けさせていただきますよろしくお願いいたします🙇‍♀️', '1', 1, '2023-09-15 23:26:33', '2023-09-15 23:26:33', 0),
(303, 2, 4, '保木さん、こんばんは😊\r\n返信遅くなりましたー💦💦\r\n\r\nはい。仕事の合間にできそうなワークはドンドン隙間時間に入れてください！その方が時短になるしジッとしている時間もなくので良いかと思います🙆‍♀️\r\n目標設定は新たな野望が生まれたり別に気になるところが出てきたり…で、もし目標が変わってきたのなら変えましょうか？と言うお伺いでした😊なので、最初の目標通り❗️太もも🦵ホッソリを目指しましょう✊✊✊全然！無謀ではないですよ👍やってやりましょう✊\r\n\r\nと。言うことでワークの内容少し変えてみます。よろしくお願いいたします😊', '2', 1, '2023-09-15 23:30:15', '2023-09-15 23:30:15', 0),
(304, 7, 4, '樹里さん、おはようございます☀️\r\n\r\nワーク！フルでしっかりやってみていかがでしたか？なかなかに気持ちよかったと思うのですが😁隙間時間。上手に次ってくださいね👍\r\nラーメン、チャーハン🍜OKです🙆‍♀️ボリュームあるものは早い時間に食べちゃおー😙\r\nコンサル🎵お待ちしてますよぉ〜❣️', '2', 1, '2023-09-16 08:56:10', '2023-09-16 08:56:10', 0),
(305, 5, 4, 'しずかさん、おはようございます☀️\r\n\r\n先日はコンサルお疲れさまでした😊\r\nプランク。いかがですか⁉️続けられそうですか？今週のワークの方も更新していますのでチェックしてください！\r\nお腹〜❗️頑張って〜❣️', '2', 1, '2023-09-16 09:09:19', '2023-09-16 09:09:19', 0),
(306, 6, 4, 'りおさん、おはようございます☀️\r\n\r\nボール2コ！上手く使えてますか❓\r\nボール同士はくっつけている方がズレにくいですよぉ〜👍\r\nまた、わからない事がありましたら連絡くださいねー☺️👋', '2', 1, '2023-09-16 09:11:24', '2023-09-16 09:11:24', 0),
(307, 5, 4, 'SHOCOさん、ご連絡遅くなりすみません！\r\nプランクした次の日ちゃんと筋肉痛きました😳お腹筋肉痛になったの久々です😂\r\nとにかく継続できるようにがんばります！\r\nワークの更新もありがとうございます！', '1', 1, '2023-09-17 00:15:22', '2023-09-17 00:15:22', 0),
(308, 5, 4, 'しずかさん、おはようございます☀️\r\n\r\nおっー‼️腹筋キターー😆👍\r\nヨッシャ🙌頑張りましょ😊\r\n\r\n腰痛、来なくなって良かったです！\r\n右腰が突っ張るのはやはりまだ歩き方にクセがあるんでしょうね。それもボール＆ストレッチでリセットできたからー⭕️です👍', '2', 1, '2023-09-17 09:43:54', '2023-09-17 09:43:54', 0),
(309, 5, 4, '…ちなみに。\r\n私はの返信はあまり気にしないで大丈夫です🙆‍♀️\r\n私が思ったことをメッセージに残していってまーす❗️\r\nもちろん、嬉しいご報告や🙋などは大歓迎です💜', '2', 1, '2023-09-17 09:45:10', '2023-09-17 09:45:10', 0),
(310, 3, 4, '原田さん、おはようございます☀️\r\n\r\nお仕事に勉強に！ご苦労さまです😊\r\n疲れている時こそワークのパワーと効果が感じられる！と私も思います。\r\nドンドン、ボールと仲良くなってスペシャリストになってくださいっ👍', '2', 1, '2023-09-17 09:48:46', '2023-09-17 09:48:46', 0),
(311, 7, 4, '樹里さん、おはようございます☀\r\n\r\nワーク！順調に進んでいるようですね👍その調子で頑張りましょう😊\r\n\r\n本日、グループレッスン❗️お待ちしてますっ❣️楽しみです💜', '2', 1, '2023-09-18 08:40:31', '2023-09-18 08:40:31', 0),
(312, 6, 4, 'りおさん、おはようございます☀\r\n\r\n本日、コンサルよろしくお願いいたします😊\r\n今回はレッスンしてみますか？\r\n何かリクエストありましたらくださいねー👍', '2', 1, '2023-09-18 08:42:14', '2023-09-18 08:42:14', 0),
(313, 2, 4, '保木さん、おはようございます☀️\r\n\r\n新しいワークはいかがでしょうか⁉️\r\n今日のグループレッスンの時にまた感想お聞かせくださいね😊\r\nよろしくお願いしまーす❣️', '2', 1, '2023-09-18 08:44:15', '2023-09-18 08:44:15', 0),
(314, 2, 4, 'こんにちは！連休で、やること多くて、新しいワークまだ出来てません(T_T)グループレッスンまでにやれたらやってみます', '1', 1, '2023-09-18 12:28:40', '2023-09-18 12:28:40', 0),
(315, 2, 4, '今日のグループレッスンですが、今日はお休みします。連休の疲れをレッスンで癒やして週明けにのぞみたかったのですが、アーカイブを楽しみにしてます！', '1', 1, '2023-09-18 17:40:14', '2023-09-18 17:40:14', 0),
(316, 7, 4, 'グループレッスン初めてで緊張します🥲💦\r\nよろしくお願いいたします！', '1', 1, '2023-09-18 18:24:39', '2023-09-18 18:24:39', 0),
(317, 2, 4, 'わかりましたぁー！\r\nでは、お疲れがとれてからで大丈夫ですので新しいワークの感想お聞かせくださーい☺️', '2', 1, '2023-09-18 18:31:23', '2023-09-18 18:31:23', 0),
(318, 7, 4, 'すみません、グループレッスンのアクセス先？はどこかに記載されていますか？💦', '1', 1, '2023-09-18 19:04:11', '2023-09-18 19:04:11', 0),
(319, 7, 4, 'アクセス先わからずグループレッスンに入れていません🙇‍♀️💦\r\n会員ページ内を見ましたがわからず😭', '1', 1, '2023-09-18 20:05:23', '2023-09-18 20:05:23', 0),
(320, 7, 4, 'レッスンお疲れさまでしたー❗️\r\n\r\n今日は足🦵スペシャルでしたがあったまりましたかね？\r\n足裏外体重は悪くはないのだけど、ただしっかりと親指の母指球も踏んで欲しい！そうすると足裏のアーチが生まれます👍\r\n足裏は身体の土台。頑張りましょうね😊', '2', 1, '2023-09-18 22:19:08', '2023-09-18 22:19:08', 0),
(321, 6, 4, 'りおさん、お疲れさまでしたー❗️\r\n\r\nワーク、しっかりできているようですね👍隙間時間も上手く利用できてるし🙌\r\nあと、職場の隙間にできそうな動きってありますか？\r\n次回からのワーク。少し動きのあるものを入れたいなと😙また教えてください。\r\n\r\nあと。日報くださいねー😅', '2', 1, '2023-09-18 22:23:03', '2023-09-18 22:23:03', 0),
(322, 7, 4, 'レッスンありがとうございました！\r\n足首、距骨のメニューはすごく苦手だと思うので今日のレッスン復習しながら取り組みたいと思います☺️\r\n\r\n1つ質問し忘れたことがあったのですが、毎日の②~④のワークは順番通りじゃなくてもいいのでしょうか？\r\n', '1', 1, '2023-09-19 00:28:02', '2023-09-19 00:28:02', 0),
(323, 7, 4, '樹里さん、おはようございます☀️\r\n\r\nワークの順番は②と③は順番通りに。\r\n④などはそこだけ取り出して時間のある時に…でもOKです😊\r\n\r\nゆっくり通してできそうな時は順番通りにやっていただけたらと思います👍', '2', 1, '2023-09-19 09:48:39', '2023-09-19 09:48:39', 0),
(324, 6, 4, '日報入れました！遅くなってすみません💦\r\n夜勤なら何でもできます！\r\n例えばどんな動きですか？？', '1', 1, '2023-09-19 23:13:34', '2023-09-19 23:13:34', 0),
(325, 6, 4, 'ちょっとトレーニング系の動きを入れようかな？と。\r\n立ったままできるワークとかストレッチならできるかな？と思うのですが。', '2', 1, '2023-09-19 23:30:13', '2023-09-19 23:30:13', 0),
(326, 7, 4, 'しょうこさんこんばんは！\r\nありがとうございます！\r\n順番も意識してみますね😊\r\n\r\n昨日のレッスンでしっかり足のケアしたので今日は足だけ暑いくらいポカポカでした！\r\nフォーム確認しながらしっかりやるのが本当に大切だなと思いました✨\r\n\r\n今週木曜日も個別コンサルお願いしております！今回は立ち姿勢と歩き方について教えていただきたいです！\r\n土日旅行でたくさん歩くので、その前にしっかり習得したいです！\r\nよろしくお願いいたします💪', '1', 1, '2023-09-19 23:32:05', '2023-09-19 23:32:05', 0),
(327, 7, 4, '樹里さん、こんばんは😊\r\nでしょー⁉️足裏ちゃんとすればめっちゃポカポカになるんです‼️\r\n\r\nはい。木曜日ですね😊\r\n歩き方やりましょう✊よろしくお願いいたします🙇‍♀️', '2', 1, '2023-09-19 23:37:05', '2023-09-19 23:37:05', 0),
(328, 6, 4, '大丈夫です！', '1', 1, '2023-09-20 12:00:47', '2023-09-20 12:00:47', 0),
(329, 6, 4, 'おはようございます😆\r\n\r\nワークの内容更新してます❣️\r\n今週！この内容で頑張ってかださーい😊', '2', 1, '2023-09-20 12:17:31', '2023-09-20 12:17:31', 0),
(330, 6, 4, 'それと、歩き方〜❗️\r\n\r\n歩く時、基本足は前に「出さず」下に下ろして「後ろにける」です。なかなかに難しいですが、練習してみてください。つま先もできるだけ真っ直ぐ出しましょう。そして、もう一つ大事なこと。自分の足の始まり位置のイメージ。足は股下からではなく腰のあたりから「足」だと思って歩いてみてください。それだけで重心の位置が変わってきますよ。\r\nそしてこまめにストレッチ。ふくらはぎと脛の前側足の甲をしっかり伸ばしてください。脛のストレッチは正座になって片方の膝を少し持ち上げると伸びます😊\r\nまた、わからなかったらメッセージください❣️', '2', 1, '2023-09-20 20:40:16', '2023-09-20 20:40:16', 0),
(331, 6, 4, 'ありがとうございます！\r\n歩き方以前教えてもらった歩き方を意識して\r\n歩くと足が楽です！ずっと意識してられないのですぐ痛くなってしまいしますが💦\r\nナースシューズ、スニーカーに変えても\r\n疲れるので意識していきます！', '1', 1, '2023-09-21 16:08:54', '2023-09-21 16:08:54', 0),
(332, 5, 4, 'しずかさん、こんばんは😊\r\n\r\n四つ這いのポーズですね。\r\n膝の上に骨盤が乗っているか位置を確認してください。\r\nそして、バランスをとりはじめると骨盤が前側にズレていっていないかみてください。\r\n腿の前や上げている足に力が入るのは入りますが、お腹も一緒につかえているか？お腹きら足が上がっていれば多少足に力が入っているのは許容範囲です😊', '2', 1, '2023-09-21 19:48:05', '2023-09-21 19:48:05', 0),
(333, 2, 4, '保木さーん❗️こんばんは😊\r\n\r\nワーク！ハマってきましたか⁉️😆やったー🙌変な筋肉痛などもありませんか？\r\n腕と足。繋がっているので足の代謝が上がれば腕も細くなりまーす👍\r\n頑張りましょう✊', '2', 1, '2023-09-21 19:50:28', '2023-09-21 19:50:28', 0),
(334, 2, 4, '保木さん、こんにちは😊\r\n\r\n先週からのお疲れはとれましたか？\r\nまた、ワークでわかりづらいところなどありましたらメッセージくださいね😊', '2', 1, '2023-09-23 14:21:09', '2023-09-23 14:21:09', 0),
(335, 6, 4, 'りおさん、こんにちは😊\r\n\r\n歩き方。いかがですか⁉️\r\n\r\n意識し過ぎてどこか別の場所が疲れたり痛みがでたりはありませんか？\r\n気になることがありましたらメッセージくださいねー😊', '2', 1, '2023-09-23 14:23:13', '2023-09-23 14:23:13', 0),
(336, 3, 4, '原田さん、こんにちは😊\r\n\r\nお腹の調子、整いつつありますね👍\r\n\r\nヒール履くようになるとまた少し胸ハリ姿勢になりがちです。実際そうしないとバランスがとりづらいんですよね💦💦足が疲れたらワーク！がもう習慣になっておられると思いますが、後ろ重心、胸ハリになってるかも？を思い浮かべながらリセット！の意識でワークしてくださーい❗️\r\n足裏の踏み方も変わってくるので地味距骨ワークや足指マッサージも隙間時間に入れてくださいね😊👍', '2', 1, '2023-09-23 14:33:45', '2023-09-23 14:33:45', 0),
(337, 5, 4, 'しずかさん、こんにちは😊\r\n\r\n24日の件、了解です🫡\r\nしばらく忙しくなられるようですが体調崩さないように気をつけてくださいね。また落ち着いたらコンサルよろしくお願いいたします☺️', '2', 1, '2023-09-23 17:13:49', '2023-09-23 17:13:49', 0),
(338, 5, 4, 'SHOCOさん、わざわざ調整くださったのに本当に申し訳ございません😭💦\r\nご了承いただきありがとうございます😣\r\nお気遣いのお言葉までありがとうございます😭\r\nはい！またよろしくお願いいたします！', '1', 1, '2023-09-24 00:35:21', '2023-09-24 00:35:21', 0),
