(510, 2, 4, 'おはようございます！昨日はグループレッスンとコンサルありがとうございました。コンサル時に腰の痛みについて話していましたが、寝る前に太腿とお尻のストレッチで少しのばして寝ましたが、朝は腰痛なかったです。', '1', 1, '2023-11-14 07:39:14', '2023-11-14 07:39:14', 0),
(511, 2, 4, 'こんばんは😊\r\n\r\nおぉー❗️よかったです🙌\r\n少しずつ立つ時のポジション変えていってくださいね😊\r\n\r\n明日までにはワークの更新できていると思いますのでよろしくお願いいたします😆', '2', 1, '2023-11-14 22:19:54', '2023-11-14 22:19:54', 0),
(512, 7, 4, '樹里さん、こんにちは😊\r\n\r\nワークの方更新しています！\r\nウエスト❗️頑張りましょう😊\r\n肋骨は無理に締めようとするよりも楽に呼吸をしていくと動くようになりますよ☺️👍', '2', 1, '2023-11-16 16:43:17', '2023-11-16 16:43:17', 0),
(513, 6, 4, '莉緒さん、こんにちは😊\r\n\r\nワークの方更新していますのでよろしくお願いいたします❗️\r\n立ち方！綺麗になってます👍\r\n腰が前に落ちないように気をつけてくださいね☺️', '2', 1, '2023-11-16 17:12:08', '2023-11-16 17:12:08', 0),
(514, 7, 4, 'しょうこさんこんにちは！\r\n\r\nワーク更新ありがとうございます！\r\n新しいのやってみますね！\r\n最近、比較的食欲が落ち着いていたおかげもあってか少しサイズダウンできました！\r\n\r\n残り頑張りますよろしくお願いします🙇‍♀️', '1', 1, '2023-11-17 16:58:49', '2023-11-17 16:58:49', 0),
(515, 7, 4, '樹里さん、こんにちは😊\r\n\r\nおっ！サイズ変わってきましたか⁉️\r\n目に見えてくるとやる気も出てきますねっ👍\r\n頑張っていきましょう😊', '2', 1, '2023-11-18 11:40:50', '2023-11-18 11:40:50', 0),
(516, 5, 4, 'しずかさん、こんにちは😊\r\n\r\nストレッチの時などに腰が捻れていたり腰を反らせすぎていませんか？\r\nプランクの時に腰が落ちていませんか？\r\n辛い時はプランクお休みしてもいいので肋骨絞めて呼吸と腹式呼吸のワークをしましょう。それと肩と肩甲骨を下げた状態で呼吸とワークができるように練習をしてください。\r\n腰痛の原因の可能性としては\r\n体幹の繋がりを上手く使えていない。\r\n冷えと筋肉の緊張。\r\nストレス。\r\n内臓の不調。\r\nしずかさんの場合腰の1箇所を無意識のうちに押してしまう癖があるか、もしくは謎の腹痛もあるので一度お医者さんに相談してみるのもいいかも知れません。', '2', 1, '2023-11-18 11:52:12', '2023-11-18 11:52:12', 0),
(517, 2, 4, '保木さん、こんにちは😊\r\n\r\nワーク！全部できて良かったです😊👍はい。バックキックなどの大きな動きは回数やキープ時間調整してください❗️内腿、腿裏使える脚🦵目指して頑張りましょう〜💨💨', '2', 1, '2023-11-18 11:54:28', '2023-11-18 11:54:28', 0),
(518, 5, 4, 'アドバイスありがとうございます🙇‍♀️\r\n早速やってみたいと思います！\r\n講座で言うと何番のものになりますでしょうか？\r\nあまり続くようであればお医者さんに相談してみます、、、', '1', 1, '2023-11-18 14:04:09', '2023-11-18 14:04:09', 0),
(519, 2, 4, '保木さん、おはようございます☀️\r\n\r\n太もも筋肉痛❗️いいですね😊\r\nその分しっかりとストレッチで老廃物外は流せば〜👍', '2', 1, '2023-11-19 10:09:19', '2023-11-19 10:09:19', 0),
(520, 2, 4, 'すみません💦後半日本語がおかしくなりました😅\r\n\r\n老廃物を外へ流せばgoodですー😆\r\n\r\n週次報告もありがとうございました！\r\n診断していきますね😊', '2', 1, '2023-11-19 10:10:45', '2023-11-19 10:10:45', 0),
(521, 5, 4, '講座番号13-1と、ワークには入れていませんでしたが、講座番号20をやってみてください。\r\n一度に全部しなくてもOKです😊\r\n13か20のどちらかでー❗️', '2', 1, '2023-11-19 10:35:14', '2023-11-19 10:35:14', 0),
(522, 5, 4, 'わかりました！\r\nありがとうございます！✨', '1', 1, '2023-11-19 20:00:05', '2023-11-19 20:00:05', 0),
(523, 3, 4, 'しょうこ先生こんばんは。\r\n今日久しぶりに写真をとってお送りしました。\r\nここのところ長時間飛行機に乗ったり、デスクワークの連続かと思えば外出が続いたりと不規則な上に、お酒の席も多くて体重増えてしまい嫌な予感はしていたのですが、目に見えて脚が太くなってました😢\r\nちゃんとできていなくてごめんなさい。\r\nまだしばらく続くので簡単には戻らないかもしれませんができることを引き続き頑張っていきます。\r\nちなみに1番好きなワークが基本の2と3なので、最低でもそれだけは毎日やっています。\r\nもし、それ以外でこれをやると今の私の状態にはいい、というお勧めがあれば教えてください！', '1', 1, '2023-11-19 22:00:49', '2023-11-19 22:00:49', 0),
(524, 2, 4, 'ありがとうございます！昨日は、バレトン前から左の股関節が筋肉痛？詰まってる？のか、固まってるのか、すごく動きが悪くて、日々のワークで身体を内観するのが定着しているのがよくわかりました。バレトン後に、家族で出かけて帰りがけに温泉でマッサージしてきたので、筋肉痛はまだでてないです＼(^o^)／お尻の筋膜はがしを忘れたらお尻は筋肉痛です😁', '1', 1, '2023-11-20 07:02:38', '2023-11-20 07:02:38', 0),
(525, 3, 4, '原田さん、おはようございます☀️\r\n\r\nおぉ。益々お忙しい日々💦💦\r\n\r\nそうですね。生活が乱れると体重だけでなく脚も浮腫むし太くなるし😭\r\n\r\n基本のワークにプラスするとしたら足指のマッサージとしたから上に向けてのリンパ流しなのですが、軽く2〜3回撫でるだけでもOKです👌\r\nそれと単純にふくらはぎのストレッチ！壁にに両手をついた壁ドンでふくらはぎを伸ばしてください😊\r\n\r\n今は時間が取れない時期だからしょうがない！と割り切るのもありです😊\r\nワークできない！がストレスになっていかないよーに。何をすれば脚に良かったのかどんな動作が続いたら脚が疲れるのか浮腫むのか？などを観察する期間にするのもいいかもです😊\r\n\r\n大丈夫ですよー。身体は意外と学習能力高いですから😉👍', '2', 1, '2023-11-20 09:02:34', '2023-11-20 09:02:34', 0),
(526, 2, 4, '保木さん、おはようございます☀️\r\n\r\nレッスンしながら自分の身体を内観できてきたなんてー✨✨素晴らしいです😊\r\nはい。そうやって少しずつ自分で調整できてくるんです❗️\r\n頑張っていきましょう😉👍', '2', 1, '2023-11-20 09:05:10', '2023-11-20 09:05:10', 0),
(527, 5, 4, 'SHOCOさん、こんばんは✨\r\nもしご存知であればぜひ教えていただきたいのですが、\r\n私は末端冷え性で特に足元が冷えやすく、家で過ごす時や寝る時の冷え対策グッズが何かないかなと思い探しております。\r\n靴下は足指にあまり良くないとのことでしたので、避けたほうが良いでしょうか？\r\nもし何かおすすめグッズがございましたら教えていただきたいです☺️', '1', 1, '2023-11-20 20:15:00', '2023-11-20 20:15:00', 0),
(528, 5, 4, 'しずかさん、こんにちは😊\r\n\r\n冷え対策ですよねー😅\r\nまずは身体を温めるものを食べる飲む。そして肩から肘までを暖かくしておく。ふくらはぎから足首までを暖かくしておく。\r\nお家で過ごす時のグッズでしたらやはりレッグウォーマーかな？\r\nモコモコのレッグウォーマーでもいいと思いますし、もしも普通のを試してみてもイマイチ…でしたら「イオンドクター」と言うメーカーさんがあります。私も大昔に買ってずっと使ってました（ここのところはそこまで冷えなくなったのでタンスの奥にしまってありますが）ウチのスポーツクラブでも毎年売り出します。お値段は結構しますが長持ちします。もしよろしければググってみてください😊', '2', 1, '2023-11-21 10:36:11', '2023-11-21 10:36:11', 0),
(529, 5, 4, 'イオンドクターはじめて聞きました！\r\n調べてみますー！\r\n肩から肘は気にしてなかったです😳\r\nレッグウォーマー買います！\r\nありがとうございます🙇‍♀️', '1', 1, '2023-11-21 18:28:14', '2023-11-21 18:28:14', 0),
(530, 5, 4, 'はい。\r\n調べてみてくださーい❣️\r\n\r\n\r\nそれと、20-2のワークですよね。\r\nこつをつかむまで少し時間がかかるかも？でも、試行錯誤している時間もワークになるので頑張りすぎずに頑張ってください！', '2', 1, '2023-11-21 23:39:20', '2023-11-21 23:39:20', 0),
(531, 5, 4, 'そうなんですね🥲\r\nコツコツやってみます🍀\r\nありがとうございます☺️', '1', 1, '2023-11-22 13:23:25', '2023-11-22 13:23:25', 0),
(532, 2, 4, '保木さん、こんにちは😊\r\n\r\nそうですね。慣れてくると自分のペースで気持ちよくできるのは良い点なのでが段々と自分のクセも出てきます。\r\nはい。たまーに基本に戻ってみてください😊', '2', 1, '2023-11-25 12:06:56', '2023-11-25 12:06:56', 0),
(533, 2, 4, 'でも❗️気づきがある！は素晴らしいです👍その感性を育てていきましょう😆\r\n\r\nそして、明日❣️\r\nご足労おかけしますがよろしくお願いいたします✨✨', '2', 1, '2023-11-25 12:08:19', '2023-11-25 12:08:19', 0),
(534, 6, 4, '莉緒さん、こんにちは😊\r\n\r\n週次報告ありがとうございます✨✨\r\nまた、この先のプランを立てたらワーク更新したいと思います。少しお待ちくださいねー😄', '2', 1, '2023-11-25 12:11:32', '2023-11-25 12:11:32', 0),
(535, 7, 4, '樹里さん、こんにちは😊\r\n週次報告ありがとうございます✨✨\r\nまた、ワーク更新しましたらお知らせいたしますね😊\r\n\r\n今回のワークの感想などもあればお聞かせください！', '2', 1, '2023-11-25 12:13:38', '2023-11-25 12:13:38', 0),
(536, 2, 4, 'いつもありがとうございます😊こちらこそ、遠方よりお忙しい中、大変ありがたいです！よろしくお願いいたします！', '1', 1, '2023-11-25 21:16:54', '2023-11-25 21:16:54', 0),
(537, 2, 4, '保木さん、おはようございます☀\r\n\r\n昨日はお疲れさまでした😊\r\n情報量過多ですみませんでした💦\r\nでも、実際にお会いして一緒にレッスンさせていただ井出とても楽しかったです！ありがとうございました✨✨\r\n\r\n昨日このレッスンのポイントを今週のワークのコメント欄に書いておきます。基本ワークは保木さんの気持ちの良いものを選んでいただいてOKです。お仕事などで固まった筋肉と関節をワークで緩めつつ日常生活の動きを変えていってください😊\r\nよろしくお願いいたします✨✨', '2', 1, '2023-11-27 08:44:48', '2023-11-27 08:44:48', 0),
(538, 6, 4, '莉緒さん、プランクや股関節周りの軽い筋トレ系はいかがですか❓\r\n\r\n気持ちよくできているものと辛い！だったりよくわからない？と思うワークがあれば教えてください😊', '2', 1, '2023-11-27 14:49:19', '2023-11-27 14:49:19', 0),
(539, 2, 4, 'こんにちは〜！昨日は、ありがとうございました!リアルレッスンとっても楽しかったです。\r\nとにかくちゃんと覚えて置かなくては！とインプットに意識し過ぎて質問どころでなく、日頃のお礼や感謝も伝えられず、失礼しました。帰宅後は、緊張と疲れで早々に眠ってしまいました。今朝、ボールワークして股関節の広がり方が均等で、いつもよりよく動いていて、おおっ！と驚きました。今日は、内側を意識した歩き方と、立ち姿勢のときのお尻の位置を意識してました。\r\n少しずつ、無意識で動けるようにできたらと思います。', '1', 1, '2023-11-27 16:02:08', '2023-11-27 16:02:08', 0),
(540, 2, 4, '保木さん、おはようございます☀️\r\n\r\nいえいえ。こちらこそ。\r\nご挨拶もそこそこにレッスンでしたね💦すみません😅\r\nはい。無意識で！が目標です！が。\r\nやはりこまめにチェックしないとズレていきます。日々チェック＆リセットで美しい姿勢をキープさせましょう❗️今後ともよろしくお願いいたします😊', '2', 1, '2023-11-28 08:42:28', '2023-11-28 08:42:28', 0),
(541, 6, 4, 'こんにちは！\r\nあまり時間がとれておらず、\r\n新しいのは動画見ながら寝てしまったりしていて💦\r\n筋トレ系あんまりできてないんです…\r\nすみません😭\r\n隙間時間にできるものに偏ってしまってます🥹', '1', 1, '2023-11-28 10:06:07', '2023-11-28 10:06:07', 0),
(542, 6, 4, 'こんにちは！\r\nあまり時間がとれておらず、\r\n新しいのは動画見ながら寝てしまったりしていて💦\r\n筋トレ系あんまりできてないんです…\r\nすみません😭\r\n隙間時間にできるものに偏ってしまってます🥹', '1', 1, '2023-11-28 10:06:07', '2023-11-28 10:06:07', 0),
(543, 8, 4, '【運営事務局より】\r\n川口 沙織 様\r\nこの度は、ご入会頂き誠に有難うございます。\r\n\r\n沙織さんの自己実現に向けスタッフ一同全力でサポートさせて頂きますので　\r\n運用上で不明点やご質問等ある場合は、左記メニューの [コミュニケーションツール] よりご連絡ください。\r\n講師もしくは事務局より、2営業日以内にご回答させて頂きます。\r\n\r\nそれでは3カ月間全力でサポートしますので、宜しくお願いいたします！', '3', 1, '2023-11-29 12:05:01', '2023-11-29 12:05:01', 0),
(544, 8, 4, '沙織残念❗️こんにちは😊\r\n美脚プログラムへようこそ❣️\r\nご入会ありがとうございます✨✨\r\n\r\n今日から美脚ワークはじまります。\r\n初めてやる動作や初めて聞く用語などもあると思いますが、質問や疑問がありましたら何でも！聞いてくださいね😊美脚ワークが沙織さんの日常になるように、そして沙織さんの毎日が楽しいものになるようにお手伝いができれば幸いです❗️\r\n３ヶ月間、一緒に頑張っていきましょう💪どうぞ、よろしくお願いいたします💜', '2', 1, '2023-11-29 15:41:18', '2023-11-29 15:41:18', 0),
(545, 7, 4, '樹里さん、こんにちは😊\r\n\r\n食べ過ぎた分はリセットできましたかぁー⁉️これから年末年始、外食の機会が増えますが…少しでもいいので…セーブ…お願いしますねぇ😅', '2', 1, '2023-11-29 15:44:53', '2023-11-29 15:44:53', 0),
(546, 7, 4, 'しょうこさんこんばんは！\r\nメッセージなかなか返信できなくて申し訳ありません🙇‍♀️\r\n\r\n少しずつですが体調が回復してきています！\r\n残り時間少なくなってしまいましたが、個別コンサルお願いできればと思ってます、よろしくお願いします😭\r\n\r\n食事も意識しますね‪‪💦‬\r\n\r\n\r\nしばらく浮腫みにくく、週次報告でもサイズダウンしてきて順調だなと思っていたのですが、寒くなってきた影響もあるのかまた浮腫みやすくなってしまいました🥶\r\n\r\n自宅にいる時は椅子に座っていることがほとんどですが、寒くてついつい足を引っ込めて椅子の上であぐらをかいてしまいます😫あぐらって良くないでしょうか？', '1', 1, '2023-11-29 23:20:32', '2023-11-29 23:20:32', 0);
INSERT INTO `messages` (`id`, `user_id`, `staff_id`, `message`, `sender`, `is_read`, `created`, `modified`, `is_deleted`) VALUES
(547, 7, 4, 'おはようございます☀\r\n\r\nねー。寒くなってきましたねー😵😵😵\r\n椅子の上であぐらですよね。\r\n私もやります。足を組んで座ったり正座で座るよりはいいとは思います。\r\nただ…長時間となるとやはり足や仙骨には良くなくて💦とはいえ立つ以外は座るわけなのでどうしよえもないのですが😅\r\nので、私は色々な格好をしてます😁\r\nあぐらかいたり、横に崩したり、テーブルの上に足を乗せたり💦できるだけ左右均等に、時間もできるだけ均等に。腰はできるだけ伸ばして…など考えながらね。あと目線もできるだけ水平になるようにタブレットなどを置いてます。ダメな時は立ってます💨なかなかに大変な作業ですが少し気をつけているだけでも随分ちがうと思うので、特に浮腫みにはね！頑張っていきましょう😊', '2', 1, '2023-11-30 09:27:44', '2023-11-30 09:27:44', 0),
(548, 7, 4, 'コンサル＆yumicoさんとのインタビューもよろしくお願いいたします😊', '2', 1, '2023-11-30 09:28:32', '2023-11-30 09:28:32', 0),
(549, 7, 4, 'こんばんは！\r\nメッセージありがとうございました☺️\r\n座り方意識してみます！あとは湯船に浸かって体あたためるようにします♨️\r\n\r\nこちらこそ、インタビューとコンサルよろしくお願いいたします🙇‍♀️', '1', 1, '2023-12-01 01:22:38', '2023-12-01 01:22:38', 0),
