(837, 12, 4, 'こんばんは😊\r\nおぉぉっーー‼️\r\nミニスカ履けた⁉️ヤッター🙌🙌🙌\r\nはい。人は思い立った時から変わりはじめるんですー😆👍\r\n\r\nではっ！次はスキニーパンツ🩳買いに行きましょうか？😁', '2', 1, '2024-03-09 20:41:52', '2024-03-09 20:41:52', 0),
(838, 12, 4, 'ここまであきらめずにこれたのもＳHOCO先生とレッスンしたおかげです…圧倒的感謝です…\r\n明日にでもGUかユニクロでスキニーパンツ漁ってきます！！！', '1', 1, '2024-03-09 20:48:56', '2024-03-09 20:48:56', 0),
(839, 12, 4, 'いえいえいえいえ💦\r\n頑張ったのりこさんのおかげですよぉ〜😊👍\r\nはい❗️\r\nまた見せてくださいねっ！楽しみにしていまーす😆🙌', '2', 1, '2024-03-09 20:51:39', '2024-03-09 20:51:39', 0);
INSERT INTO `messages` (`id`, `user_id`, `staff_id`, `message`, `sender`, `is_read`, `created`, `modified`, `is_deleted`) VALUES
(840, 12, 4, 'のりこさん、おはようございます☀️\r\n\r\nグループレッスンお疲れさまでした！\r\n股関節難しいですね💦\r\nワークの方にしゃがむ動作の解説動画をプラスしておきました。これは1日に何回！って言うものではなくしゃがむ時のポイントなどを参考にしていただけたらと😊☝️\r\nなかなか簡単には筋肉の向きは変わっていきませんが、力ずくではなくボールで優しく緩めつつ少しずつです。\r\nその時に関節のカタチを思い浮かべながら行うと効果的ですよー！', '2', 1, '2024-03-11 08:53:13', '2024-03-11 08:53:13', 0),
(841, 16, 4, '真由美さん、おはようございます☀\r\n\r\nグループレッスンお疲れさまでした😊しゃがみ動作！意外と難しいですよね💦でも、しゃがむだけで身体中の関節が動きます。1日のうちに何度かしゃがむ！やってみてくださいね。\r\nワーク自体は増やしていません。が、コンサルやグループでやった動作を毎日のワークや隙間時間に挟み込んでいってください！\r\nレッグウォーマー、太ももピチピチ🦵も引き続きよろしくお願いしまーす❗️😊', '2', 1, '2024-03-11 08:58:12', '2024-03-11 08:58:12', 0),
(842, 11, 4, 'つかささん、おはようございます☀\r\n\r\nオヤツー！勧められると辛いね💦でも、お付き合いも大切なのでその時は美味しくいただきましょう✌️その分ワークとお腹引っ込めながらのインナーマッスル腹筋を頑張りましょう😆\r\nファイティン✊', '2', 1, '2024-03-11 09:01:38', '2024-03-11 09:01:38', 0),
(843, 18, 4, 'かなこさん。おはようございます☀\r\n\r\nコンサル夜がメインですが、ご希望があれば午前中に対応できる日もありますのでご相談くださいねー😊', '2', 1, '2024-03-11 09:02:47', '2024-03-11 09:02:47', 0),
(844, 10, 4, '陽子さん、おはようございます☀️\r\n\r\n今週もワークの方、引き続き頑張ってください！変更をプラスしていない分歩き練習💨💨力まず股関節を伸び伸び使ってくださいね😊', '2', 1, '2024-03-11 09:09:36', '2024-03-11 09:09:36', 0),
(845, 10, 4, '承知しました。骨盤の重心を意識して歩くと上半身が常に前にあるイメージなのですが、これで合ってますかね？\r\n\r\n股関節の伸びを意識して歩きます！', '1', 1, '2024-03-11 13:57:07', '2024-03-11 13:57:07', 0),
(846, 10, 4, '承知しました。骨盤の重心を意識して歩くと上半身が常に前にあるイメージなのですが、これで合ってますかね？\r\n\r\n股関節の伸びを意識して歩きます！', '1', 1, '2024-03-11 13:57:09', '2024-03-11 13:57:09', 0),
(847, 10, 4, '承知しました。骨盤の重心を意識して歩くと上半身が常に前にあるイメージなのですが、これで合ってますかね？\r\n\r\n股関節の伸びを意識して歩きます！', '1', 1, '2024-03-11 13:57:10', '2024-03-11 13:57:10', 0),
(848, 10, 4, 'はい。少し上半身が前の感じです😊\r\nので、少し押し出してあげるだけで前に進む〜🎵です✌️\r\nはーい！よろしくお願いしますっ💜', '2', 1, '2024-03-11 14:18:25', '2024-03-11 14:18:25', 0),
(849, 18, 4, 'ありがとうございます😭\r\n午前中ですと、15、18、21日辺りはいかがでしょうか。', '1', 1, '2024-03-11 15:24:48', '2024-03-11 15:24:48', 0),
(850, 18, 4, 'かなこさん、返信ありがとうございます。\r\nすみません🙏仰っていただいた日は全部仕事が入っています💦\r\n私の予定ですと…\r\n火曜日…3/19、4/23以外ならOK\r\n水曜日…3/20、4/3、4/24OK\r\nあとは土日でしたら大体大丈夫なのですが…いかがでしょうか？\r\n3/24の日曜日は✖️です🙏', '2', 1, '2024-03-11 16:51:04', '2024-03-11 16:51:04', 0),
(851, 18, 4, 'それでは4/3の9:00〜いかがでしょうか？', '1', 1, '2024-03-11 17:43:00', '2024-03-11 17:43:00', 0),
(852, 18, 4, 'はい。承知いたしました。\r\n4/3 9:00〜お取りしておきますね😊\r\nよろしくお願いいたします！\r\n\r\nワークの方は大丈夫ですか？\r\nわからないことや質問がありましたらメッセージくださいね！', '2', 1, '2024-03-11 17:45:17', '2024-03-11 17:45:17', 0),
(853, 18, 4, 'はい、ありがとうございます。よろしくお願いします！', '1', 1, '2024-03-11 19:00:44', '2024-03-11 19:00:44', 0),
(854, 16, 4, '祥子さんこんばんは✨\r\n\r\n昨日はありがとうございました😊\r\nしゃがみ動作難しかったです😂\r\n分かりました！\r\n隙間時間にしゃがむ動作入れてみます！\r\nその他ワークも引き続き頑張ります🤩', '1', 1, '2024-03-11 20:44:32', '2024-03-11 20:44:32', 0),
(855, 12, 4, '日曜日はグループレッスンありがとうございました！\r\n悪の元凶なんじゃないかというぐらい\"膝の中心と曲がる向き\"と\"つま先(人差し指と中指の間)\"が合わず…\r\n\r\n距骨と股関節はどうにかしたいですが…なかなか強敵ですね。\r\n後1か月無いですができるところまで頑張ります！\r\n\r\nワーク追加ありがとうございます！\r\nお風呂掃除のときにしゃがむので、しっかりやりまーす！\r\n\r\nそして4点質問です。長くなってしまったので、質問ごとに区切って出しますね！\r\n(文字が難しければ、次回の個人レッスンでお話させてください。30分が厳しければ連続で1時間で見てもらえると助かります！)', '1', 1, '2024-03-11 22:03:36', '2024-03-11 22:03:36', 0),
(856, 12, 4, '1)つま先をまっすぐ＋肩幅に開いてしてしゃがんだ時の膝の向き\r\n\r\n太ももは外旋するので膝も若干外を向くかと思います。\r\n(講座19の最後はこうなっててほしい！というところ)\r\n\r\nが、狙いは膝が正面を向くものなのでしょうか？', '1', 1, '2024-03-11 22:03:45', '2024-03-11 22:03:45', 0),
(857, 12, 4, '2)足指、つま先の向きについて\r\n\r\nつま先 = 人差し指と中指の間、が正面に向くのが狙い、というのは理解しています。\r\nが、未だに距骨がはまらない＆足指の第3関節が全然浮き出てこないということで何か間違えてる気がしています。\r\n\r\nそこで質問なのですが、、\r\n足指がまっすぐとは、どのような状態を指すのでしょうか。\r\n上手く質問できずもどかしいのですが…\r\n\r\n講座6で言うところの\r\n中足骨(足の甲の中にある骨)と、足指が同じ方向を向くのが理想なのでしょうか。\r\n私の指、中足骨と指が同じ方向を向いてなくて…', '1', 1, '2024-03-11 22:04:01', '2024-03-11 22:04:01', 0),
(858, 12, 4, '3)膝とつま先の向きが異なる件について\r\n\r\n今回のレッスンを受けてということで…\r\n私の場合は股関節の横の動き？(外旋？)が弱いのか\r\n膝に意識を飛ばしすぎているのでしょうか…\r\n\r\n膝は閉じないと！と思ってここまで生きてきたのですが、、\r\n足を閉じるときは、\r\nつま先、くるぶしくっつけてから膝関節の真横をくっつけたほうがいいんですかね。\r\n\r\n今まで、ひざをくっつける＝膝の皿(若干体の前側)のところ合わせるイメージだったのですが\r\n実は膝の皿というよりももうちょっと真横でそろえるものなのでしょうか。', '1', 1, '2024-03-11 22:04:20', '2024-03-11 22:04:20', 0),
(859, 12, 4, '4)上半身について\r\n\r\n今回のしゃがみ方や、立ち方だったりを学んできて\r\n下半身はだいぶまともになってきたかと思います。\r\n\r\nそうなるとだんだん上半身が気になってきています。\r\n\r\nどうしても癖で顎を出しがちで、(ストレートネック)\r\n戻そうと思って顎を引くと、2重顎的なことになります。(多分顎だけひいてる)\r\n背中を壁につける意識でいると前かがみ(猫背)になった、というか\r\n下腹ポッコリ(骨盤後傾)になった気がしてどうすればいいのか…と迷っています。\r\n\r\n背中のS字カーブの正しい位置もわからず自己流でやるのが怖いので\r\n何か意識するポイントやコツがあれば教えてほしいです。', '1', 1, '2024-03-11 22:06:45', '2024-03-11 22:06:45', 0),
(860, 11, 4, 'しょうこさん、こんばんは！\r\n\r\n了解致しました🫡\r\n\r\n今日も食べすぎなので\r\n明日から控えます。。\r\n\r\n急遽、旦那が来月から転勤になり\r\n物件探しや最後に遊ぶ約束が\r\n絶えず連絡がきてるので\r\nなかなかダイエット進めれてません💦', '1', 1, '2024-03-12 00:14:14', '2024-03-12 00:14:14', 0),
(861, 12, 4, 'まず、質問その1\r\n\r\nつま先真っ直ぐでしゃがんだ場合、膝の向きも前向きです。\r\nでも、のりこさんの場合はまだつま先を少し外へ開いて練習してください。', '2', 1, '2024-03-12 00:18:04', '2024-03-12 00:18:04', 0),
(862, 12, 4, '質問その2\r\n\r\n中足骨と足指の向きは同じ。\r\n距骨のズレと足指の方向を整えていくためにはやはり足裏の踏み方を整えていく必要があります。\r\n足指の真裏で床を踏めるように。→すんごいチカラで踏むわけではないです。親指と小指の母指球でゆかが踏めること。足裏の小指側のふちを踏めること。土踏まずを持ち上げられること。この辺りの練習をしていくとだんだんと距骨と足指が整ってきます。', '2', 1, '2024-03-12 00:22:50', '2024-03-12 00:22:50', 0),
(863, 12, 4, '質問そのら3\r\n\r\nはい。真横同士を揃えるイメージです。素直にファスナーを閉めるように足の骨同士を揃えます。\r\n閉じないと！って思うとほんの少し内股な感じになるでしょ？ではなくー、真横！です。', '2', 1, '2024-03-12 00:25:19', '2024-03-12 00:25:19', 0),
(864, 12, 4, '質問その4\r\n\r\n重心の位置を土踏まずの上。\r\n骨盤の傾きを少し前傾方向へ。　\r\n肋骨を少し閉じる。\r\n顎を無理に引くのではなく胸の骨を上に引き上げる。その胸の骨の上にアタマを乗せる。\r\nこんなイメージです😊', '2', 1, '2024-03-12 00:28:51', '2024-03-12 00:28:51', 0),
(865, 11, 4, 'ありゃ。\r\nじゃぁ、つかささんもいっしょにお引越しですか⁉️', '2', 1, '2024-03-12 00:30:39', '2024-03-12 00:30:39', 0),
(866, 12, 4, '早速の回答ありがとうございます！\r\n次のレッスンまでやってみます！\r\n\r\n質問1)足を肩幅に開いて、ちょっとつま先外に向けてしゃがみの練習しますね！\r\n質問2)気を抜くと親指の母指球で踏めてないので意識します\r\n質問3)足の骨同士、ですね。内またにならないようにします\r\n質問4)あんまり背中を意識しなくてもいいんですね。。まずは肋骨の一気を付けます！', '1', 1, '2024-03-12 20:20:11', '2024-03-12 20:20:11', 0),
(867, 11, 4, 'そうなんです💦\r\n\r\n今日の個人レッスンも\r\nお願いしてましたが\r\nやる事が多すぎてキャンセルで\r\nお願いします😢\r\nすいません。。', '1', 1, '2024-03-14 17:28:38', '2024-03-14 17:28:38', 0),
(868, 11, 4, 'わかりました！\r\n急なことで大変ですね💦💦\r\nあとプログラム少しなのにね。\r\nあまりにもワークできなさそうでしたら一度yumicoさんの方にもご相談くださいね。', '2', 1, '2024-03-14 17:30:31', '2024-03-14 17:30:31', 0),
