INSERT INTO `users` (`id`, `member_number`, `uuid`, `email`, `password`, `last_name`, `first_name`, `last_name_kana`, `first_name_kana`, `zipcode`, `prefecture`, `city`, `address`, `tel`, `birthday`, `sextype`, `is_continue`, `start_datetime`, `end_datetime`, `staff_id`, `staff_message`, `staff_week_message`, `payment`, `sales_history`, `note`, `created`, `modified`, `is_deleted`, `light_plan`, `is_light_plan_first_event`, `staff_plan`) VALUES
(1, '1000001', 'ec7b35c69a31b9c34152c69ea2bacd', 'msato@someonelikeyou.co.jp', '$2y$10$CZbaBLH6Ig426gNl7HVrg.0MpUfsu.mcasnJQUsQbAR/hUBM6ncF.', 'テスト', 'ユーザー1', 'てすと', 'ゆーざー1', '1410032', NULL, '品川区', '大崎２－９－２－５０５', '090-5320-4451', '1973-04-21', '2', 0, '2023-07-30 14:50:00', '2026-12-31 23:59:00', 6, '特に講座②③④は美脚に向けた全てに繋がる基本ワークです。\r\n何事も基礎が大事！！　しっかり習慣化できるよう反復して実践していきましょう！', '実施期間:  2023.08.06(月)～2023.08.12(日)\n\n　【講座②】朝・夕で1日2回実施\n　【講座③】朝・夕で1日2回実施\n　【講座④】朝・夕で1日2回実施\n　   ----------今週より追加-------------\n　【講座⑥】朝 or 夕のどちらかで1日1回\n　【講座⑨】朝 or 夕のどちらかで1日1回', '現金振込', '', 'テスト用にアカウント作成をしてます。', '2023-07-30 14:55:02', '2023-12-31 14:02:22', 0, 0, 0, 0),
(2, '1000003', '157800e849406d64b76b02e2bf36eb', 'everyday_is_a_new_day201801@ezweb.ne.jp', '$2y$10$F/QNuUep/J.D1NFMseyhju7l098fBV.NMAKBmRcvb7HzYCxB7ePDK', '保木', '雅江', 'ほき', 'まさえ', '3200834', NULL, '宇都宮市', '陽南4-13-13', '09074109467', '1977-01-01', '1', 1, '2023-08-01 00:00:00', '2024-11-03 23:59:00', 4, '〈目標❗️太ももまわり45cm〉\r\n\r\n★ヒップヒンジ…背骨を伸ばして股関節からお辞儀。背中にタオルやモップなどを持ってやるとわかりやすいです。ヒザを少し緩めてお辞儀。背骨はつむじの方に伸びていくのを感じましょう。\r\n★ウォーキング…股関節は少し狭め！イメージは内腿寄りの辺りからまっすぐ足を出しましょう。そして親指の母指球に繋げます。足は前にはあまり出さず後ろに蹴ってくださいね❗️\r\n★ヒザ抱っこのボールワークの時に足を一度揃えて抱えてみて身体の中心にきているかをよくチェックしてください。部屋のひだりがわを見る練習もお願いしまーす❣️\r\n\r\n★今回の保木スペストレッチ\r\n＊ボールを股関節に挟み内腿を締める練習。10秒程キープして休憩×3セットくらい。外腿が疲れない程度でOK。\r\n＊その後、内腿ストレッチ。→これもやはり外腿が疲れない程度でね☝️\r\n上記の２つを2〜3回繰り返し。\r\n＊足腰幅で骨盤ゆらゆら。小さな動きでOK左右均等に。壁に沿ってやるのもOK。つま先は正面、外向きふた通り。それぞれ骨盤前に出して振ったり後ろに引いて振ったり。\r\n前屈した時の骨盤のズレを壁で確認もOK🙆‍♀️\r\n\r\n基本のワークや足指マッサージはもう習慣になってきたので大丈夫だと思います😊\r\n引き続き足指、足裏ほぐしてください❗️\r\n\r\n今回も引き続き股関節周りの筋肉を緩めたいと思います。保木スペシャルストレッチをしながら更にリンパを流していこうと思います！\r\nそして、座り姿勢でもしっかりとコアが使えるようになる為に20-1のワークを入れました😊\r\nバックキックは残してますが、前回同様関節を動かすイメージで😊☝️でも！背中は真っ直ぐですよぉ〜！反り腰注意です😊力を抜いて振り子のイメージですよぉ〜！', '実施期間:  2023.11.16(木)～2023.11.22(水)\r\n\r\n　【講座②】朝 or 夕で1日1回\r\n　【講座③】朝 or 夕で1日1回\r\n　【講座⑦】朝 or 夕で1日1回\r\n　【講座⑬-1】朝 or 夕で1日1回←削除\r\n　【講座⑱-3】朝 or 夕で1日1回←削除\r\n　【講座⑪-1】週3回\r\n　【講座⑪-4（バックキックのみ）】週3回\r\n　【講座⑳-2】朝 or 夕で1日1回\r\n　【講座⑱-1】朝 or 夕で1日1回\r\n　【講座⑱-4】朝 or 夕で1日1回\r\n　【講座⑳-1】朝 or 夕で1日1回\r\n　   ----------今週から追加-------------\r\n　【講座⑧】朝 or 夕で1日1回\r\n　   ----------お風呂などながらでできる時に-------------\r\n　【講座⑥】朝 or 夕で1日1回', '銀行振込　一括', '※インスタ→LINEステップよりオーガニック顧客として契約', '１９７７年生まれ\r\n職業：図書司書館', '2023-07-30 18:13:36', '2024-10-07 17:53:10', 0, 0, 0, 0),
(3, '1000002', 'b2521009e3331b49b2ef3424c969ef', 'sachi.otto@gmail.com', '$2y$10$bEWghFQ4KpsTwLP2RI1c9OjSwDpxWSdGR3/v9qEaDNzIT6dWxQICa', '原田', '佐知子', 'はらだ', 'さちこ', '1410032', NULL, '品川区', '大崎２－９－２', '', '1975-07-17', '1', 0, '2023-08-01 00:00:00', '2024-06-30 23:59:00', 4, '〈ミニスカでバレエ🩰1ヶ月集中プロジェクト❗️❗️〉\r\n\r\n★↓↓のワークは続行です！\r\nそれにプラスしてコンサルの時にやったつま先立ち2種目を入れてみてください！\r\n1. つま先V字で立って「カカトをつけたまま」つま先立ち\r\n2. つま先を内に向けて立ってつま先立ち。このとき母指球は5本ともできるだけつけましょう。小指は指先しかつかないかも？ですが、それはOK🙆‍♀️です。\r\n★基本のワークにプラス講座⑨や⑩、⑱のうつ伏せ胸ボールなどを、中心に行っていきましょう。足裏で床を掴むワークも忘れずに！特に左足〜！\r\n↓↓\r\n今回も足裏ワーク少しレベルアップした講座12は引き続き頑張りましょう！\r\nあと、全身の代謝と血液循環を良くするためのワークもキープ。\r\n新しいワークとしましては今回上半身の動きを入れてみました。足裏と骨盤の位置が整ってきたのに合わせて肩、肋骨も活性化させていきたいです！肩の力を抜いて頑張り過ぎないよーにやってみてくださいね😊', '実施期間:  2024.05.15〜\r\n\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日2回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日2回\r\n　[【講座④】](https://ashiyasebikyaku.com/mypage/courses/view/25/9)朝・夕で1日2回\r\n　[【講座⑦】](https://ashiyasebikyaku.com/mypage/courses/view/28/12)朝 or 夕で1日1回\r\n　[【講座⑧】](https://ashiyasebikyaku.com/mypage/courses/view/29/13)朝 or 夕で1日1回\r\n　[【講座⑫】](https://ashiyasebikyaku.com/mypage/courses/view/33/17)朝 or 夕で1日1回\r\n　[【講座⑯】](https://ashiyasebikyaku.com/mypage/courses/view/37/21)週3回\r\n　[【講座⑱】](https://ashiyasebikyaku.com/mypage/courses/view/39/23)朝 or 夕で1日1回→週3回\r\n＝＝＝＝＝＝＝＝今週から追加＝＝＝＝＝＝＝＝＝＝＝＝\r\n　[【講座⑩】](https://ashiyasebikyaku.com/mypage/courses/view/31/15)朝 or 夕で1日1回\r\n　[【講座⑬】](https://ashiyasebikyaku.com/mypage/courses/view/34/18)朝 or 夕で1日1回\r\n　[【講座⑭-3】](https://ashiyasebikyaku.com/mypage/courses/view/35/29)朝 or 夕で1日1回', '現金振込', '※上村からの紹介顧客', 'エステ経験あり\r\n職業：外資系医療メーカーOL', '2023-07-30 18:45:58', '2024-05-15 22:18:30', 0, 0, 0, 0),
(4, '1000004', '34f3e4fb3294dee98545c8474a442f', 'ysonoda@someonelikeyou.co.jp', '$2y$10$gSrFU/hgzuYqPrh7rWoZUu2YZrkB7gPXPkksTfJgwBXSryCwwbV06', 'テストユーザー', '２', 'テストユーザー', '２', '', NULL, '', '', '', '1979-07-17', '', 0, '2024-06-30 00:00:00', '2024-12-31 11:56:00', 4, '特に講座②③④は美脚に向けた全てに繋がる基本ワークです。\r\n何事も基礎が大事！！　しっかり習慣化できるよう反復して実践していきましょう！', '●皆さんの姿勢診断完了までの間、【STEP1】Ready to 美脚ファンデーション講座の下記講座を実施してください。\r\n\r\n　【講座①】バランスボールの基本的な考え方とボディーマッピングを学ぶ（1回学習でOK）\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回　美脚メイキングの要となる仙骨をゼロリセットする（毎日実施）\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)仙腸関節の歪みを矯正して小腹周りをスッキリさせる（毎日実施）\r\n　[【講座④】](https://ashiyasebikyaku.com/mypage/courses/view/25/9)距骨の歪みを矯正して美脚のベースを作る（毎日実施）\r\n　[【講座⑤】](https://ashiyasebikyaku.com/mypage/courses/view/25/11)腸活により内臓の機能を高めて、浮腫みや脂肪を燃焼させる（解説動画を1回学習でOK）', '', '', 'おその用テストユーザー', '2023-08-01 11:57:48', '2024-06-30 22:54:07', 0, 0, 0, 0),
(5, '1000005', 'bb9d98ccf975266639429a9ce99424', 'mbaisbhi33@gmail.com', '$2y$10$HbDmX04A41p8QjlAPkkOleZ3n1AIy2wBQHBpoYy6lmKMDMTvCG7ju', '末富', '静佳', 'すえとみ', 'しずか', '2320072', NULL, '横浜市南区', '永田東', '09059688509', '1988-03-03', '1', 0, '2023-08-21 00:00:00', '2024-01-31 23:59:00', 4, '〈タイトな衣装でブタイニ上がる❗️〉\r\n\r\n★今回もワークの内容に大きな変化はありませんが腹圧を入れる練習と呼吸のための肋骨を緩めるワークをプラスしました。\r\nプランクなどの体幹トレーニングの質を更にアップさせたいと思います。そして腰痛とサヨナラできる身体を作りたい！です。\r\nあとは基本のワークはこまめにやっていきましょう！↓↓↓👇😊👇\r\n講座①～④は美脚を手に入れるための土台となる基本ワークです。\r\n\r\n\r\n\r\n不明点等あれば [コミュニケーションツール ]へ気軽に質問をお願いします。 ', '●下記講座を反復してワークしてみてください。\r\n→実施期間:  2024.01.22(月)～2024.01.28(日)\r\n\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日1回\r\n　[【講座④】](https://ashiyasebikyaku.com/mypage/courses/view/25/9)朝・夕で1日1回\r\n　【講座⑦-1】朝・夕で1日1回\r\n　【講座⑦-3】朝・夕で1日1回\r\n　【講座⑫】週に3回→😊削除\r\n　【講座⑭】週に3回\r\n　【講座⑧】朝・夕で1日1回\r\n　【講座⑲】朝・夕で1日1回\r\n＝＝＝＝＝＝今週から追加＝＝＝＝＝＝＝＝＝＝＝＝＝＝\r\n　【講座⑦-2】朝・夕で1日1回\r\n　【講座⑬-1】朝・夕で1日1回\r\n　【講座⑰】朝・夕で1日1回', '24回払い(Stripeにて24カ月受領課金)', '※インスタ→LINEステップよりオーガニック顧客として契約', 'VISAデビットカードのみ保有（1回払→可、分割払→不可）\r\n※2023年10月に京都へ移住予定\r\n〒616-8335\r\n京都府京都市右京区嵯峨石ヶ坪町51-14', '2023-08-19 12:41:18', '2024-01-24 13:01:03', 0, 0, 0, 0),
(6, '1000006', '6e7f5bda732ff24f64453277cf1de6', 'p.joir2@gmail.com', '$2y$10$b9TzaFbSL0JFrw89fhS2.OjZX3CTzD5BNIsyPgo2qwqwGmt/BoMq.', '中村', '莉緒', 'なかむら', 'りお', '1920919', NULL, '八王子市', '七国1-22-5 クレアーレ101号室', '090-4093-5412', '1994-07-20', '1', 1, '2023-08-21 00:00:00', '2024-05-31 23:59:00', 6, '〈足元の見えるスカートで記念撮影❗️〉\r\n\r\n講座①～④は美脚を手に入れるための土台となる基本ワークです。\r\n\r\n★足裏の3点ポイントを踏んで足首の捻れ直し！足元と鏡に写った足を見比べながらつま先、足首、脛、ヒザ、股関節を真っ直ぐに揃えていきましょう！\r\n\r\n★プランク30秒×3セット\r\n肩と肩甲骨を引き下げて、恥骨と肋骨を引き寄せて身体の中心に力が入る！感覚を掴みましょう！\r\n\r\n★ボールでゴロゴロはワーク動画にはありませんが、背中にボールを入れて仰向けで呼吸＆背中丸めて起き上がる元の位置に戻るの繰り返し動作と首の後ろにボール。仰向け、横向き気持ちのいいところにボール入れてください。あとうつ伏せで鎖骨の前にボール。ゆっくり呼吸した後、腕を肩甲骨から動かしてみてください。隙間時間には手で頭を持って首のストレッチです。\r\n重心の確認もまめにねー！O脚直しのユラユラです😊\r\n\r\n★つま先V字カカトをつけたまま足首屈伸。腿やお尻が緊張しない場所を探す。楽にヒザが外を向くようになったら、つま先を揃えて（足裏置き直してOK）お辞儀して戻るお辞儀して戻る。←戻る時にあまりヒザにチカラが入らないように注意です！\r\n\r\n\r\n\r\n\r\n不明点等あれば [コミュニケーションツール ]へ気軽に質問をお願いします。 ', '●下記講座を反復してワークしてみてください。\r\n→実施期間:  2023.11.16(木)～2023.11.22(水)\r\n\r\n　【講座②】朝・夕で1日2回\r\n　【講座③】朝・夕で1日2回\r\n　【講座④】朝・夕で1日2回\r\n　【講座⑧】朝or夕で1日1回\r\n　【講座⑪】週２ー３回\r\n　【講座⑩】朝or夕で1日1回\r\n　スペシャルメニュー　O脚瞬殺ワーク　朝or夕で1日1回\r\n========今週から追加=================================\r\n　【講座⑬-1】朝or夕で1日1回\r\n　【講座⑭-1】週２ー３回\r\n　【講座⑭-2】週２ー３回\r\n　【講座⑳】週２ー３回\r\n========好きな時に=================================\r\n 【講座⑧】好きな時に　\r\n 【講座⑱】好きな時に', 'カード一括（契約後、顧客側にて12回分割に変更）', '※インスタ→LINEステップよりオーガニック顧客として契約', '', '2023-08-19 12:45:57', '2024-05-02 11:06:27', 0, 0, 0, 0),
(7, '1000007', 'a2c00c9b7cd6746ef88dc23240b33e', '12p041shop@gmail.com', '$2y$10$F/R8cwCRUCQajbiFez9WSOmog6A/Tnrw0Ffn1yK3tWxcU48uDzZWa', '近藤', '樹里', 'こんどう', 'じゅり', '9501211', NULL, '新潟市南区', '白根古川131-1-202', '08011377110', '1994-03-18', '1', 0, '2023-09-09 00:00:00', '2024-01-31 23:59:00', 4, '〈目指せ‼️メリハリボディ！いつでも推しに会いに行ける身体を手に入れる‼️〉\r\n\r\n講座①～③は美脚を手に入れるための土台となる基本ワークです。\r\n\r\n講座11-3→週に2〜3回\r\n①樹里スペシャルワーク→足裏をしっかり踏んで足首が真っ直ぐになるように足元か鏡を見ながら整える。この立ち方したまま↓↓\r\n②講座20-腹圧\r\n③講座16-カカト歩き、仙骨叩き、ローリング\r\n④講座10-ボールに肩\r\n⑤講座18-鎖骨ににボールリンパ流し、胸鎖関節にボールうつ伏せ、脚プルプル\r\nひざ裏鼠蹊部マッサージ、腸マッサージ、\r\n⑥講座6-ボールを挟んで\r\n\r\n隙間時間に→講座8→背骨を360°\r\nお風呂で→講座6→足指のストレッチ\r\n\r\n何か不明点等あれば遠慮なく、左記メニューの[コミュニケーションツール]より\r\nどんどん質問してくださいね。\r\n\r\n自分が目指す成果を手に入れるために頑張っていきましょう！！', '●下記講座を反復してワークしてみてください。\r\n→実施期間:  2023.12.15(金)～2023.12.22(金)\r\n\r\n　【講座⑳-2】朝・夕で1日１回\r\n　【講座⑯】朝・夕で1日１回\r\n　【講座⑩】朝・夕で1日１回\r\n　【講座⑱】朝・夕で1日１回\r\n　【講座⑥】朝・夕で1日１回\r\n　【講座②】朝・夕で1日2回\r\n　【講座③】朝・夕で1日2回\r\n　【講座⑧】朝・夕で1日１回\r\n\r\n　【講座⑪-3】週２－3回\r\n　【講座⑪-4】バックキックとバタ足　週２－3回\r\n', 'カード一括（契約後、顧客側にて分割に変更）', '', '', '2023-09-04 11:22:02', '2024-06-30 15:41:26', 0, 0, 0, 0),
(8, '1000008', '1fe291557b45ff50d9b746760e8a98', 'niboguchi@yahoo.co.jp', '$2y$10$CAGglY9lkG8EfbWlNJJ7rOkRyZqU4v6l87IF1nFJL8r.YrIPgw.L.', '川口', '沙織', 'かわぐち', 'さおり', '5780905', NULL, '東大阪市', '川田２ー１２－１７', '090-5463-7725', '1993-07-08', '1', 0, '2023-12-01 00:00:00', '2024-03-15 23:59:00', 4, '＊3ヶ月後の目標＊\r\n『かわいいビキニで沖縄旅行👙』\r\n※中間目標※\r\n「スリムパンツを自信を持って履く！」\r\n\r\n講座②〜④は基本のワークです。\r\n動画を見なくても自分のペースでリラックスしながらできるところまで覚えていきましょう❗️\r\n\r\n★距骨を入れる時の姿勢と足指の向きに注意です。チカラが入りすぎても距骨は上手く滑ってくれないので小さな動きでもOK！ゆるりと関節動かしていきましょう。疲れる前にお休みですよ。\r\nそして、最後にふくらはぎのストレッチ2種目と脛と足の甲のストレッチをしてくださいね😊\r\n★今回、新しく足指のストレッチと上半身のワークをプラスしています。\r\n足裏❗️しっかり使えるようにしていきましょう。やはり足裏も骨、筋肉たくさんあります。美脚を作る土台！整えましょうね。\r\n寒くて固まりやすい上半身のストレッチも入れました！気持ち良く動かして身体の中から温めてくださいね。', '●下記講座を反復してワークしてみてください。\r\n→実施期間:  20240115～20240121\r\n\r\n\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日1回\r\n　[【講座④】](https://ashiyasebikyaku.com/mypage/courses/view/25/9)朝・夕で1日1回\r\n＝＝＝＝＝＝追加＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝＝\r\n　[【講座⑥】](https://ashiyasebikyaku.com/mypage/courses/view/27/10)朝・夕で1日1回\r\n　[【講座⑧】](https://ashiyasebikyaku.com/mypage/courses/view/29/13)朝・夕で1日1回', 'Stripe（カード一括）', '', '職業：先生（中学校）', '2023-11-29 12:03:19', '2024-01-24 13:05:19', 0, 0, 0, 0),
(9, '1000009', '37a49e0e7a5f10d9d07ce7116874a1', 'tinkerbell1985@outlook.jp', '$2y$10$./NXXDsSHC0QRVM1/zndbeaa4/J6vDJmYDZpQeUIPIPJEgrFmDsoG', '林', '美彩', 'ハヤシ', 'ミサエ', '3310823', NULL, 'さいたま市北区', '日進町2-1769', '09075167800', '1985-03-23', '1', 0, '2023-12-16 00:00:00', '2024-03-16 23:59:00', 4, '＊3ヶ月後の目標＊\r\n『素敵なワンピで彼をを振り向かせるぞ！』\r\n※中間目標※\r\n「ロングブーツとショートパンツ「着こなす！」\r\n\r\n講座②〜④は基本のワークです。\r\n動画を見なくても自分のペースでリラックスしながらできるところまで覚えていきましょう❗️', '●下記講座を反復してワークしてみてください。 \r\n→実施期間: 20240122～20240128 　\r\n\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日1回\r\n　[【講座④】](https://ashiyasebikyaku.com/mypage/courses/view/25/9)朝・夕で1日1回\r\n　[【講座⑥-1】](https://ashiyasebikyaku.com/mypage/courses/view/27/10)朝・夕で1日1回実施', '', '獣医、動物向けに腸活や舌診断を実施している', '', '2023-12-15 12:48:23', '2024-01-24 13:04:26', 0, 0, 0, 0),
(10, '1000010', '3f486502e715b9e8c16a3cf83cc15a', 'youtan300@gmail.com', '$2y$10$cuHn.WnlcBUsYb6pn.lWiOJsPhcMIjIfmrvFYHwqbfrYw5pz/1foC', '山本', '陽子', 'ヤマモト', 'ヨウコ', '2100023', NULL, '川崎市川崎区', '小川町8-9 501', '03-3704-1933', '1979-09-21', '1', 1, '2023-12-18 00:00:00', '2024-09-21 23:59:00', 4, '＊3ヶ月後の目標＊\r\n『体脂肪率減！＆スキニーパンツを履きこなす！』\r\n\r\n講座②〜③は基本のワークです。\r\n動画を見なくても自分のペースでリラックスしながらできるところまで覚えていきましょう❗️\r\n\r\n★今回はとにかく基本のワークをしっかりやり込みましょう❗️\r\n背中が床にしっかりついているか？背骨を中心に左右の身体の重さは同じか？など、細かいところに注目しながら行ってみてください❗️\r\n★今回追加\r\n講座11のトレーニング系、お好きなのを取り入れてください！頑張り過ぎない程度でどーぞ。\r\n足指のストレッチや青竹、土踏まず作るワークはながらで続行です！\r\n\r\nあとは腹筋系！肋骨引き締め呼吸とクリスクロス。呼吸は一日中2回程度。\r\nクリスクロスは一日一回。\r\n\r\n★講座11のpart1のひざ下にボールを丁寧に！膝の位置を整えます。\r\npart2のヒップリフトは腿裏(少し内側の方)が使えているかどーかを確認しながら行いましょう。バックキックはリキミ過ぎず股関節を伸び伸び動かしてくださいね。\r\n\r\n（隙間時間にリフレッシュ）\r\n講座⑧…背骨を柔らかくしなやかに動かすことで下半身との連動を良くしましょう😊\r\n\r\n', '●下記講座を反復してワークしてみてください。\r\n→実施期間:  2024.05.16\r\n\r\n\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日1回\r\nーー基本にプラスー\r\n\r\n[【講座⑧】](https://ashiyasebikyaku.com/mypage/courses/view/29/13)朝夕で1回\r\n\r\n＝＝＝＝＝＝追加＝＝＝＝＝＝＝＝＝＝＝＝\r\n[【講座⑫】](https://ashiyasebikyaku.com/mypage/courses/view/33/17)お腹にボールバウンス以外！朝・夕で1回\r\n[【講座⑰】](https://ashiyasebikyaku.com/mypage/courses/view/38/22)part２立ちでボール\r\n朝・夕で1回\r\n[【講座⑪　Part１】](https://ashiyasebikyaku.com/mypage/courses/view/32/16)ひざ下ボール朝・夕で1回\r\n[【講座⑪　Part２】](https://ashiyasebikyaku.com/mypage/courses/view/32/30)ヒップリフト、バックキック2日に1回', 'ストライプ分割', 'ピラティスインストラクター', '', '2023-12-15 12:52:15', '2024-08-18 17:14:43', 0, 0, 0, 0),
(11, '1000011', 'd11866f2608f8bfd3910081713e4aa', 't.8beans@gmail.com', '$2y$10$7bimmbS/TS4AhN74So6SPOpMC76XHR.UPNYQudYm2hZAVuzf.nyBS', '猪上', 'つかさ', 'いのうえ', 'つかさ', '5938311', NULL, '堺市西区', '上', '09058877292', '1994-09-12', '1', 0, '2023-12-20 00:00:00', '2024-04-20 23:59:00', 4, '＊最終目標＊\r\n『素敵なドレスでウェディングフォト!』\r\n※1ヶ月後の目標※\r\n「目指せ！Lサイズ！」\r\n※中間目標※\r\n「友達とお揃いの服でディズニーランド！」\r\n↑↑\r\nクリア❗️🎊\r\n\r\n★今回は講座7の股関節にボールにプラスボールの上で脚を大きくまわす！をプラス！\r\nのんびりと腰をら使わずやってみましょう。お尻には自然に力が入る程度です。\r\n講座8は気持ちよく背骨全体を動かして代謝を上げましょう！そして上半身と下半身のつながりを良くしましょうね。\r\n\r\n★講座11の膝下の歪み取りとクラムシェルと脚回しを入れてください。軽い動きでお尻が動いているのを確認しながらです😊\r\n★講座6はキープ\r\n\r\n講座②〜④は基本のワークです。\r\n動画を見なくても自分のペースでリラックスしながらできるところまで覚えていきましょう❗️', '●下記講座を反復してワークしてみてください。 →実施期間: 2024.04.13〜\r\n　[【講座②】](https://ashiyasebikyaku.com/mypage/courses/view/23/7)朝・夕で1日1回\r\n　[【講座③】](https://ashiyasebikyaku.com/mypage/courses/view/24/8)朝・夕で1日1回\r\nーーー基本にプラスーーーーーーーーーーー\r\n[【講座⑥】](https://ashiyasebikyaku.com/mypage/courses/view/27/10)　好きな時に\r\n\r\nーーーキープーーーーーーーーーーーーーー\r\n\r\n[【講座⑧】](https://ashiyasebikyaku.com/mypage/courses/view/29/13) 朝・夕で1日1回\r\n[【講座⑪　Part１】](https://ashiyasebikyaku.com/mypage/courses/view/32/16)\r\n[【講座⑪　Part２】](https://ashiyasebikyaku.com/mypage/courses/view/32/30)\r\n2日に1回軽くなら1日1回\r\nーーーー追加ーーーーーーーーーーーーー\r\n[【講座⑦】](https://ashiyasebikyaku.com/mypage/courses/view/28/12) 7-1の股関節にボールを置いてうつ伏せ。朝・夕で1日1回\r\n仰向けで脚を大きく回す。朝・夕で1回\r\n[【講座⑲】](https://ashiyasebikyaku.com/mypage/courses/view/40/24)朝・夕で1回\r\n', '', '', '腸活と薬膳をがっつりやる\r\nウェディングフォトとりたい\r\n\r\n3月15日～4月10日まで休会\r\n4月10日～20日まで鬼軍曹', '2023-12-15 21:06:45', '2024-04-13 21:11:43', 0, 0, 0, 0),
